  ui_story_5026_50260101_38_dialog_content = "(É melhor eu pegar um pouco de ar fresco e limpar minha cabeça.)",
  ui_story_5026_50260101_39_dialog_content = "Está tão quieto.",
  ui_story_5026_50260101_40_dialog_content = "Apenas ruínas restam agora, mas este lugar provavelmente costumava ser muito animado.",
  ui_story_5026_50260101_42_dialog_content = "Até-",
  ui_story_5026_50260101_43_dialog_content = "Chubb! Chubb!",
  ui_story_5026_50260101_44_dialog_content = "Huh? Eu me desliguei de novo? Nesse ritmo, nunca chegarei ao local de pesca, mesmo que caminhe o dia todo.",
  ui_story_5026_50260101_46_dialog_content = "Eu me pergunto o que Vice, Carleen e todos os outros estão fazendo agora?",
  ui_story_5026_50260101_47_dialog_content = "Graças à companhia de todos, nunca me senti sozinho em todo o tempo em que Soroz estava inconsciente.",
