  ui_story_5026_50260101_56_dialog_content = "... Não parece muito poderoso.",
  ui_story_5026_50260101_57_dialog_content = "<size=33>Gah...</size>",
  ui_story_5026_50260101_58_dialog_content = "Não parece muito poderoso, mas não consigo lidar exatamente com isso apenas com uma vara de pescar...",
  ui_story_5026_50260101_59_dialog_content = "Ah! Não fuja!",
  ui_story_5026_50260101_60_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5026_50260101_61_dialog_content = "Fufufu!",
  ui_story_5026_50260101_62_dialog_content = "Parece que cheguei bem na hora.",
  ui_story_5026_50260101_63_dialog_content = "Betel! Obrigado por isso!",
  ui_story_5026_50260101_64_dialog_content = "Mole-mole. Eu estava mais preocupado que minha visita repentina lhe causasse problemas, PlayerName.",
  ui_story_5026_50260101_65_dialog_content = "De jeito nenhum! Sem você, este pedaço de grama poderia ter sido destruído por Spikepests.",
  ui_story_5026_50260101_66_dialog_content = "Esses caras correm muito rápido... Oh, você veio aqui para me ver por alguma coisa?",
  ui_story_5026_50260101_67_dialog_content = "Na verdade, eu vim aqui hoje em nome da Sra. Sheol.",
  ui_story_5026_50260101_68_dialog_content = "Em nome do Sheol?",
  ui_story_5026_50260101_69_dialog_content = "Trata-se de um <color=#FFB400>conta</color> que não foi resolvido.",
  ui_story_5026_50260101_70_dialog_content = "PlayerName, você se lembra de sua aventura subterrânea na Cidade Baixa perto da Noite Eterna?",
  ui_story_5026_50260101_71_dialog_content = "Se você estiver disposto a fazer algo por mim em troca, ficarei feliz em reunir informações sobre a Cidade Baixa para você.",
  ui_story_5026_50260101_72_dialog_content = "É melhor você voltar vivo e pagar.",
  ui_story_5026_50260101_73_dialog_content = "A senhorita Vice não parece estar por perto. Ela geralmente ajuda a gerenciar suas despesas, não é?",
  ui_story_5026_50260101_74_dialog_content = "Bem, então, aqui está a conta. Por favor, dê uma olhada nisso.",
  ui_story_5026_50260101_75_dialog_content = "Vamos ver... hein?! <size=45>Esse é o preço?!</size>",
  ui_story_5026_50260101_76_dialog_content = "Eu sei. Ainda estou sonhando. Deve ser isso! Ahahaha...",
  ui_story_5026_50260101_77_dialog_content = "Você gostaria de mantê-lo no crédito, PlayerName?",
  ui_story_5026_50260101_78_dialog_content = "Posso negociar em seu nome, mas deixaremos um registro com a Srta. Jane, a Testemunha Umbraton.",
  ui_story_5026_50260101_79_dialog_content = "Isso pode afetar sua credibilidade na Umbraton, bem como o desenvolvimento a longo prazo do Cloud Gardens.",
  ui_story_5026_50260101_80_dialog_content = "Eu vou pagar! Com certeza vou pagar! Eu simplesmente não posso agora.",
  ui_story_5026_50260101_81_dialog_content = "Por favor, permita-me fazer mais uma pergunta. Como você planeja colocar as mãos nessa quantia de dinheiro?",
  ui_story_5026_50260101_82_option_content = "Montar uma barraca em Umbraton e vender minhas habilidades psíquicas?",
  ui_story_5026_50260101_83_option_content = "Pegar alguns Eclipsites Corrompidos?",
  ui_story_5026_50260101_84_dialog_content = "Um plano de negócios desleixado como esse nunca seria aprovado, PlayerName.",
  ui_story_5026_50260101_85_dialog_content = "Deixe-me pensar... Cloud Gardens é um lugar bem legal.",
  ui_story_5026_50260101_86_dialog_content = "A paisagem é linda, os recursos são abundantes e você pode encontrar muitas criações celestitas únicas.",
  ui_story_5026_50260101_87_dialog_content = "Chubb?",
  ui_story_5026_50260101_88_dialog_content = "A-Você está me pedindo para vender Cloud Gardens? Ou vender Chubbs?",
  ui_story_5026_50260101_89_dialog_content = "Outros mercadores da Umbraton provavelmente proporiam algo semelhante.",
  ui_story_5026_50260101_90_dialog_content = "Mas esta sua casa não veio facilmente, não é?",
  ui_story_5026_50260101_91_dialog_content = "O que quero dizer é que, se você se esforçar mais para consertá-lo, poderá obter um lucro considerável.",
  ui_story_5026_50260101_92_dialog_content = "Tenho vergonha de admitir, mas aconteceu tanta coisa ultimamente que mal tive tempo de organizar meus pensamentos.",
  ui_story_5026_50260101_93_dialog_content = "Portanto, não consegui administrar minha nova casa tão bem quanto gostaria.",
  ui_story_5026_50260101_94_dialog_content = "E como você acabou de ver, até Eclipsites estão aparecendo aqui.",
  ui_story_5026_50260101_95_dialog_content = "Exatamente quando todos desaparecem!",
  ui_story_5026_50260101_97_dialog_content = "Por favor, diga a Sheol que sou grato por sua ajuda e não esquecerei o pagamento que devo a ela.",
  ui_story_5026_50260101_98_dialog_content = "Eu entendo. Vou solicitar um período de carência para você, PlayerName.",
  ui_story_5026_50260101_99_dialog_content = "Você tem um plano para lidar com esses Eclipsites?",
  ui_story_5026_50260101_100_dialog_content = "Quem sabe de onde eles saíram...",
  ui_story_5026_50260101_100X1_dialog_content = "Eu pensei que o Acorde da Lei havia purgado Eraveil de todos os Eclipsitas.",
  ui_story_5026_50260101_100X2_dialog_content = "Mas já faz um tempo desde que as coisas aconteceram no Obelisco do Retorno, então talvez esses Eclipsitas vagaram de outros lugares.",
  ui_story_5026_50260101_100X3_dialog_content = "Bem, se são apenas alguns Spikepests, até eu deveria ser capaz de...",
  ui_story_5026_50260101_101_dialog_content = "E se forem...",
  ui_story_5026_50260101_102_dialog_content = "Que tal contratar uma equipe de gerentes que atenda às suas expectativas para ajudar?",
  ui_story_5026_50260101_103_dialog_content = "Isso resolveria seu problema imediato com o Eclipsite e você poderia receber conselhos sobre como projetar Cloud Gardens. Dois pelo preço de um.",
  ui_story_5026_50260101_104_dialog_content = "Parece bom, mas como eu faria para encontrar candidatos adequados?",
  ui_story_5026_50260101_105_dialog_content = "Em relação ao processo de recrutamento e recursos necessários...",
  ui_story_5026_50260101_106_dialog_content = "Estou disposto a ajudá-lo com tudo isso, PlayerName. Por favor, confie em mim.",
  ui_story_5026_50260101_107_dialog_content = "Não se preocupe. Estou ajudando como amigo, então não é uma ordem de guilda.",
  ui_story_5026_50260101_108_dialog_content = "Obrigado por ser um amigo tão confiável, Betel...",
  ui_story_5026_50260101_109_dialog_content = "Vou deixar para você então!",
  ui_story_5026_50260201_1_dialog_content = "<color=#e8d9bb>Exterior de Eraveil</color>",
  ui_story_5026_50260201_2_dialog_content = "Bom. Devíamos estar nos aproximando de Cloud Gardens.",
  ui_story_5026_50260201_3_dialog_content = "Eraveil, em seu próprio canto isolado do mundo... Nem o pai teria nenhuma influência aqui.",
  ui_story_5026_50260201_4_dialog_content = "Manter-se, <color=#FFB400>Sanae</color>.",
  ui_story_5026_50260201_5_dialog_content = "M-Senhorita Nina! Espere por mim!",
  ui_story_5026_50260201_6_dialog_content = "Eu não disse para você me ligar <color=#FFB400>Nina</color> antes de sairmos? Você tem que me chamar de Nina quando estivermos lá fora!",
  ui_story_5026_50260201_7_dialog_content = "Você prometeu quando saímos de Umbraton que não seríamos seguidos, certo, Sr. Odd Jobs?",
  ui_story_5026_50260201_8_dialog_content = "Você me magoou com essas palavras, Srta. Andersen. Eu dependo da confiança dos clientes para o meu sustento.",
  ui_story_5026_50260201_9_dialog_content = "Odd Jobs fará qualquer coisa, desde salvar o mundo até procurar gatos, desde que o cliente peça...",
  ui_story_5026_50260201_10_dialog_content = "Bem, deixe-me perguntar isso então. O que ele está fazendo aqui?",
  ui_story_5026_50260201_11_dialog_content = "Argh. É por isso que eu não queria esse emprego...",
  ui_story_5026_50260201_12_dialog_content = "Bom dia, senhorita Nina. Você teve uma longa jornada, então, por favor, descanse aqui.",
  ui_story_5026_50260201_13_dialog_content = "... <color=#FFB400>Minos</color>, Quando você chegou aqui?",
  ui_story_5026_50260201_14_dialog_content = "Peço-lhe, senhorita, que não acuse o Sr. Taki injustamente. Eu realmente não segui o seu grupo.",
  ui_story_5026_50260201_15_dialog_content = "Oh o! Uma barraca, cobertor de piquenique, água com gás, sanduíches, velas perfumadas e até flores frescas...",
  ui_story_5026_50260201_16_dialog_content = "Você está muito bem preparado. Parece que você já tinha vindo aqui antes mesmo da senhora entrar pela porta do meu escritório.",
  ui_story_5026_50260201_17_dialog_content = "O mordomo de elite dos Andersens é realmente algo.",
  ui_story_5026_50260201_18_dialog_content = "Com informações suficientes, o itinerário da Srta. Nina não é tão difícil de prever.",
  ui_story_5026_50260201_19_dialog_content = "Por favor, volte comigo depois de terminar seu chá, Srta. O Mestre está preocupado com você.",
  ui_story_5026_50260201_20_dialog_content = "Eu não vou voltar! Estou fugindo de casa, sabe!",
  ui_story_5026_50260201_21_dialog_content = "Na verdade, e eu tenho minhas ordens. Mesmo que eu tenha que persegui-lo até o fim do mundo...",
  ui_story_5026_50260201_22_dialog_content = "Eu devo trazer você para casa.",
  ui_story_5026_50260201_23_dialog_content = "Fictício! O pai é um idiota!",
  ui_story_5026_50260201_24_dialog_content = "Por favor, tome cuidado com sua linguagem, Srta. Mantenha sempre a elegância de uma dama.",
  ui_story_5026_50260201_25_dialog_content = "Aham. Parece que não há mais nada para eu fazer aqui. Obrigado por seu patrocínio, Srta. Andersen.",
  ui_story_5026_50260201_26_dialog_content = "Lembre-se de deixar uma boa avaliação quando retornar ao Umbraton!",
  ui_story_5026_50260201_27_dialog_content = "Eu disse, eu não vou voltar!",
  ui_story_5026_50260201_28_dialog_content = "Pelo menos não até que eu me aproxime daquele celestita, realize meus planos e me prove! Definitivamente não até então!",
  ui_story_5026_50260201_29_dialog_content = "U-hum, Sr. Minos, eu...",
  ui_story_5026_50260201_30_dialog_content = "Não há necessidade de se explicar, Sanae. A prioridade agora é acalmar nossa jovem senhorita e voltar para casa em segurança.",
  ui_story_5026_50260201_31_dialog_content = "Você perdeu seu dever como empregada da família Andersen para fazer relatórios oportunos. Vou tomar nota disso na avaliação do final do mês.",
  ui_story_5026_50260201_32_dialog_content = "W-Vou perder meu emprego...?",
  ui_story_5026_50260201_33_dialog_content = "Você está ameaçando ela!",
  ui_story_5026_50260201_34_dialog_content = "Uau! Mana, pare com isso!",
  ui_story_5026_50260201_35_dialog_content = "O que? Estou apenas falando fatos!",
  ui_story_5026_50260201_36_dialog_content = "Eu sei que como a única pessoa da mesma idade que ela na mansão, a jovem senhorita é muito próxima de você.",
  ui_story_5026_50260201_37_dialog_content = "Essa é provavelmente a razão pela qual ela pensou que era necessário trazê-lo junto em sua escapada.",
  ui_story_5026_50260201_38_dialog_content = "No entanto, seu emprego continuado na mansão depende do seu desempenho desta vez.",
  ui_story_5026_50260201_39_dialog_content = "O-o que você quer dizer...",
  ui_story_5026_50260201_40_dialog_content = "Sanae! Por que você está demorando tanto? Vamos nos atrasar para a entrevista!",
  ui_story_5026_50260201_41_dialog_content = "C-Chegando!",
  ui_story_5026_50260201_42_dialog_content = "A determinação da jovem senhorita é muito impressionante.",
  ui_story_5026_50260201_43_dialog_content = "Então eu também terei que tomar algumas medidas drásticas.",
  ui_story_5026_50260201_44_dialog_content = "<color=#e8d9bb>Cloud Gardens: Área de entrevista com gerente</color>",
  ui_story_5026_50260201_45_dialog_content = "...",
  ui_story_5026_50260201_46_dialog_content = "<size=33>Vamos. Diga algo, PlayerName.</size>",
  ui_story_5026_50260201_47_dialog_content = "<size=33>Assim como nós praticamos!</size>",
  ui_story_5026_50260201_48_dialog_content = "R-Certo... Primeira pergunta: O que fez você se candidatar a gerente de Cloud Gardens?",
  ui_story_5026_50260201_49_dialog_content = "Isso é tão chato.",
  ui_story_5026_50260201_50_dialog_content = "O quê?",
  ui_story_5026_50260201_51_dialog_content = "Eu mudei de ideia. Pare a entrevista. Eu só queria dar uma olhada ao redor de qualquer maneira.",
  ui_story_5026_50260201_52_dialog_content = "Venha me procurar novamente se precisar que algo seja incendiado.",
  ui_story_5026_50260201_53_dialog_content = "Espero que encontre um candidato adequado em breve.",
  ui_story_5026_50260201_54_dialog_content = "Ela se foi...",
  ui_story_5026_50260201_55_dialog_content = "Não precisa ser tão cuidadoso, PlayerName. Mostre alguma seriedade como entrevistador.",
  ui_story_5026_50260201_56_dialog_content = "Você governa todo Eraveil!",
  ui_story_5026_50260201_57_dialog_content = "Próximo candidato, por favor!",
  ui_story_5026_50260201_58_dialog_content = "Olá, PlayerName. Eu sou Connolly.",
  ui_story_5026_50260201_59_dialog_content = "(Gravitas... eu sou um governante...)",
  ui_story_5026_50260201_60_option_content = "Copie a firmeza de Schwartz",
  ui_story_5026_50260201_61_dialog_content = "Por favor, sente-se, Srta. Connolly. É um prazer tê-lo aqui.",
  ui_story_5026_50260201_62_dialog_content = "Eu vou direto ao ponto. Por favor, explique sua compreensão do Cloud Gardens e do cargo de gerente.",
  ui_story_5026_50260201_63_dialog_content = "Você tem estratégias para lidar com os Eclipsites? Você é jovem, mas tem alguma sugestão? Sou todo ouvidos.",
  ui_story_5026_50260201_64_option_content = "Copie a ousadia de Reinhardt",
  ui_story_5026_50260201_65_dialog_content = "Hahaha! Venha, Connolly!",
  ui_story_5026_50260201_66_dialog_content = "Se eu estiver correto, você não tem nenhuma experiência no mundo real como gerente, certo?",
  ui_story_5026_50260201_67_dialog_content = "Perfeito. Eu aprecio aqueles com um espírito de luta.",
  ui_story_5026_50260201_68_dialog_content = "Contanto que você esteja disposto a trabalhar duro, isso não será um problema. Eu vou fazer de você um excelente \"soldado\"!",
  ui_story_5026_50260201_69_option_content = "Copie o legal de Belém",
  ui_story_5026_50260201_70_dialog_content = "Sente-se. Foi a mão do destino que trouxe sua chegada sobre nós.",
  ui_story_5026_50260201_71_dialog_content = "Você parece um pouco nervoso. Você gostaria de uma xícara de chá preto?",
  ui_story_5026_50260201_72_dialog_content = "Uh... Sr. Navegador está agindo muito estranho hoje!",
  ui_story_5026_50260201_73_dialog_content = "Eu sinto Muito! Eu não estava tentando ser difícil!",
  ui_story_5026_50260201_74_dialog_content = "Infelizmente. Eu errei novamente.",
  ui_story_5026_50260201_75_dialog_content = "Está ficando tarde. Quantos candidatos ainda restam?",
  ui_story_5026_50260201_76_dialog_content = "Aqui estão os restantes currículos. Deixe-me ver...",
  ui_story_5026_50260201_77_dialog_content = "G-Graah!",
  ui_story_5026_50260201_78_dialog_content = "Isso é candidato? Parece bastante incomum.",
  ui_story_5026_50260201_79_dialog_content = "(Eclipsiano) Eu faço qualquer coisa! Por favor, apenas me dê o trabalho!",
  ui_story_5026_50260201_80_dialog_content = "Como um Eclipse entrou?!",
  ui_story_5026_50260201_81_dialog_content = "E tem mais de um!",
  ui_story_5026_50260202_1_dialog_content = "Eu não esperava que os Eclipsites se atrapalhassem na área de recrutamento...",
  ui_story_5026_50260202_2_dialog_content = "O problema do Eclipsite em Cloud Gardens é mais sério do que eu pensava.",
  ui_story_5026_50260202_3_dialog_content = "Embora eu esteja precisando urgentemente de um ajudante, acho que terminamos as entrevistas do dia.",
  ui_story_5026_50260202_4_dialog_content = "Sinto muito... Eu prometi que ajudaria você.",
  ui_story_5026_50260202_5_dialog_content = "Não, não, tudo se resume a mim.",
  ui_story_5026_50260202_6_dialog_content = "Preciso contratar alguém, mas o salário que posso oferecer não dá nem para comprar uma réplica de pintura.",
  ui_story_5026_50260202_7_dialog_content = "Embora eu tenha muitos amigos em Umbraton...",
  ui_story_5026_50260202_8_dialog_content = "Não posso continuar confiando na boa vontade deles. Eles devem ser pagos pelo seu trabalho duro.",
  ui_story_5026_50260202_9_dialog_content = "Mas se as coisas continuarem assim...",
  ui_story_5026_50260202_10_dialog_content = "Acredito que esta seja nossa primeira reunião, Sr. Navigator.",
  ui_story_5026_50260202_11_dialog_content = "Uau, então este é o rumor de Cloud Gardens...",
  ui_story_5026_50260202_12_dialog_content = "É bem diferente do que o Umbraton Daily descreveu na série: \"Revealed! The Enigmatic Last Caelestite!\"",
  ui_story_5026_50260202_13_dialog_content = "Há mais candidatos...?",
  ui_story_5026_50260202_14_dialog_content = "H-Olá. Deixe-me dar uma olhada no seu currículo... Você deve ser Nina.",
  ui_story_5026_50260202_15_dialog_content = "Formado pela Dawn Academy com vasta experiência em desenvolvimento de negócios e gestão de recursos humanos...",
  ui_story_5026_50260202_16_dialog_content = "Exatamente!",
  ui_story_5026_50260202_17_dialog_content = "E seu parceiro Sanae pode cuidar da limpeza da casa, jardinagem e vários trabalhos de lavagem?",
  ui_story_5026_50260202_18_dialog_content = "Eu farei o meu melhor!",
  ui_story_5026_50260202_19_dialog_content = "Eles parecem os melhores candidatos até agora!",
  ui_story_5026_50260202_20_dialog_content = "Excelente, PlayerName.",
  ui_story_5026_50260202_21_dialog_content = "Você está pronto para alcançar o pico da sua vida com a minha ajuda?",
  ui_story_5026_50260202_22_dialog_content = "Hã?",
  ui_story_5026_50260202_23_dialog_content = "Farei um plano de dominação sob medida para o último celestita do continente!",
  ui_story_5026_50260202_24_dialog_content = "Dominação?! Isso é um pouco dramático...",
  ui_story_5026_50260202_25_dialog_content = "Seria uma situação ganha-ganha para nós dois. Acredito que você fará a escolha certa.",
  ui_story_5026_50260202_26_dialog_content = "O-Ok. Por favor, me dê um minuto.",
  ui_story_5026_50260202_27_dialog_content = "O currículo lista apenas as informações de duas pessoas, então quem você pode ser?",
  ui_story_5026_50260202_28_dialog_content = "Saudações. Por favor, perdoe minha intrusão. Pode me chamar de Minos.",
  ui_story_5026_50260202_29_dialog_content = "Fui treinado na Butler Training School em Lumopolis. Aqui estão meu certificado e licença.",
  ui_story_5026_50260202_30_dialog_content = "Nossa, muito profissional! Vocês três são uma equipe?",
  ui_story_5026_50260202_31_dialog_content = "Claro que não!",
  ui_story_5026_50260202_32_dialog_content = "O quê?",
  ui_story_5026_50260202_33_dialog_content = "Miss Nina e eu temos um pequeno mal-entendido. Por favor, não se importe. Eu cuidarei disso.",
  ui_story_5026_50260202_34_dialog_content = "Se não me engano, você deve estar bastante satisfeito com nossos currículos, correto?",
  ui_story_5026_50260202_35_dialog_content = "Sim...",
  ui_story_5026_50260202_36_dialog_content = "Estou honrado por ter sido selecionado onde todos os outros falharam.",
  ui_story_5026_50260202_37_dialog_content = "Bem, sobre isso... Na verdade...",
  ui_story_5026_50260202_38_dialog_content = "Você deve ter requisitos muito rigorosos para o seu gerente. A seleção final está incomodando você.",
  ui_story_5026_50260202_39_dialog_content = "Requisitos à parte, é mais o fato de que o melhor salário que posso oferecer a você é bastante...",
  ui_story_5026_50260202_40_dialog_content = "Eu tenho uma proposta.",
  ui_story_5026_50260202_41_dialog_content = "Que tal as duas senhoras e eu <color=#FFB400>dividido em dois grupos</color> e servi-lo como <color=#FFB400>gerentes de estágio</color> sem pagamento?",
  ui_story_5026_50260202_42_dialog_content = "De graça?",
  ui_story_5026_50260202_43_dialog_content = "Está correto. Atuaremos simultaneamente como seus gerentes e, no final, você contratará o grupo mais competente.",
  ui_story_5026_50260202_44_dialog_content = "Sua satisfação vem em primeiro lugar. O pagamento pode ser negociado após o período de experiência.",
  ui_story_5026_50260202_45_dialog_content = "Este é um método comum para licitações comerciais em Umbraton, espero que possa resolver suas preocupações.",
  ui_story_5026_50260202_46_dialog_content = "De graça!",
  ui_story_5026_50260202_47_dialog_content = "Senhorita Nina, Sanae, peço desculpas por tomar a liberdade de apresentar esta proposta. Se houver alguma objeção—",
  ui_story_5026_50260202_48_dialog_content = "Tudo bem, vamos competir!",
  ui_story_5026_50260202_49_dialog_content = "Não me importo com remuneração, pois o potencial do Eraveil não é algo que possa ser definido monetariamente. Você não acha?",
  ui_story_5026_50260202_50_dialog_content = "Eu acho que sim.",
  ui_story_5026_50260202_51_dialog_content = "De qualquer forma, conseguir três ajudantes muito capazes de graça é mais do que eu poderia esperar.",
  ui_story_5026_50260202_52_dialog_content = "Betel, qual é a sua opinião?",
  ui_story_5026_50260202_53_dialog_content = "...",
  ui_story_5026_50260202_54_dialog_content = "Excelente! Parece que podemos encerrar as entrevistas então!",
  ui_story_5026_50260202_55_dialog_content = "Huh? Certo!",
  ui_story_5026_50260202_56_dialog_content = "Pois então, Minos, Nina e Sanae... Conto com vocês para administrar Cloud Gardens!",
  ui_story_5026_50260202_57_dialog_content = "Está um pouco atrasado, mas... Bem-vindo ao Cloud Gardens. Espero que goste daqui!",
  ui_story_5026_50260202_58_dialog_content = "Nina, Nina Andersen...",
  ui_story_5026_50260202_59_dialog_content = "A jovem senhorita da família Andersen. Por que ela está escondendo seu sobrenome e se candidatando ao cargo de gerente na Cloud Gardens?",
  ui_story_5026_50260202_60_dialog_content = "E Sanae é uma empregada que apresentei à família Andersen recentemente.",
  ui_story_5026_50260202_61_dialog_content = "Quanto a Minos, ele é um verdadeiro mordomo.",
  ui_story_5026_50260202_62_dialog_content = "Ele estava sempre seguindo o Conde Andersen como uma sombra sempre que eu visitava sua mansão a negócios.",
  ui_story_5026_50260202_63_dialog_content = "Que grupo estranho.",
  ui_story_5026_50260202_64_dialog_content = "Mas a família Andersen é amiga do meu pai. Também ouvi dizer que Nina era uma criança séria quando estava na Dawn Academy...",
  ui_story_5026_50260202_65_dialog_content = "De qualquer forma, ainda há trabalho a ser feito, então tenho que voltar para Umbraton.",
  ui_story_5026_50260202_66_dialog_content = "Não deve haver nada para se preocupar...",
  ui_story_5026_50260301_1_dialog_content = "<color=#e8d9bb>Cloud Gardens: Fonte da Esperança</color>",
  ui_story_5026_50260301_2_dialog_content = "Foi um aviso de recrutamento publicado pela Guilda Cloudrover que me trouxe aqui, mas eu não esperava que Bethel estivesse por trás disso.",
  ui_story_5026_50260301_3_dialog_content = "Ela já estabeleceu uma relação de negócios com o Caelestita? Não menos de um aluno top.",
  ui_story_5026_50260301_4_dialog_content = "E Minos, que diabos você está tramando?",
  ui_story_5026_50260301_5_dialog_content = "Por favor, tome cuidado com sua linguagem, Srta. Mantenha sempre a elegância de uma dama.",
  ui_story_5026_50260301_6_dialog_content = "Era simplesmente uma proposta, como descrevi para você e PlayerName.",
  ui_story_5026_50260301_7_dialog_content = "Só para me impedir de ficar aqui? Você acha que eu vou para casa obedientemente assim?",
  ui_story_5026_50260301_8_dialog_content = "Eu teria pensado que alguém em quem papai confia tanto teria inventado algo mais inteligente.",
  ui_story_5026_50260301_9_dialog_content = "Você me dá muito crédito, Srta. É uma honra receber o reconhecimento do Mestre e seu reconhecimento.",
  ui_story_5026_50260301_10_dialog_content = "Eu não estava elogiando você!",
  ui_story_5026_50260301_11_dialog_content = "Deixe-me ser claro - eu não vou perder!",
  ui_story_5026_50260301_12_dialog_content = "Tenho tantas lojas em Umbraton: lojas de roupas, joalherias, lojas de armas...",
  ui_story_5026_50260301_13_dialog_content = "Uma mera propriedade rural não é nada para mim.",
  ui_story_5026_50260301_14_dialog_content = "Gerenciar um lugar como este é tão fácil quanto torta.",
  ui_story_5026_50260301_15_dialog_content = "De qualquer forma, depois que eu ganhar a confiança do celestita...",
  ui_story_5026_50260301_16_dialog_content = "Vou transformar este lugar em uma metrópole comercial que não é inferior a Umbraton de forma alguma, passo a passo!",
  ui_story_5026_50260301_17_dialog_content = "Um dia, este lugar irá mais longe do que aquela cidade morta respirando na sombra de Lumopolis.",
  ui_story_5026_50260301_18_dialog_content = "Eu vou deixar você e papai saberem que mesmo sem a riqueza e a influência da família Andersen...",
  ui_story_5026_50260301_19_dialog_content = "Eu ainda posso fazer algo de mim mesmo!",
  ui_story_5026_50260301_20_dialog_content = "Claro, Srta. Sua grande visão é admirável.",
  ui_story_5026_50260301_21_dialog_content = "Por favor, permita-me fazer mais uma proposta então.",
  ui_story_5026_50260301_22_dialog_content = "Se você pode me vencer <color=#FFB400>qualquer coisa</color> ao trabalhar em Cloud Gardens, vou desistir de trazer você para casa.",
  ui_story_5026_50260301_23_dialog_content = "Continue.",
  ui_story_5026_50260301_24_dialog_content = "Se você ganhar, eu sairei imediatamente. Não nos veremos novamente, a menos que você deseje.",
  ui_story_5026_50260301_25_dialog_content = "Você promete?",
  ui_story_5026_50260301_26_dialog_content = "Eu prometo. Além disso, você pode obter alguns ajudantes. Eu recomendo.",
  ui_story_5026_50260301_27_dialog_content = "Mas é difícil dizer quanta ajuda Sanae será para você. Afinal, ela quebrou mais xícaras de chá do que lavou na mansão.",
  ui_story_5026_50260301_28_dialog_content = "Você...",
  ui_story_5026_50260301_29_dialog_content = "M-Senhorita! Quero dizer, Nina! PlayerName é aqui.",
  ui_story_5026_50260301_30_dialog_content = "Desculpe por estar atrasado. Levei algum tempo para limpar a área de entrevista.",
  ui_story_5026_50260301_31_dialog_content = "Aconteceu alguma coisa?",
  ui_story_5026_50260301_32_dialog_content = "(Eu pensei ter visto Nina tentando acertar Minos na cabeça com seu guarda-chuva... Isso é um guarda-chuva, certo?)",
  ui_story_5026_50260301_33_dialog_content = "Nada mesmo!",
  ui_story_5026_50260301_34_dialog_content = "Não há necessidade de se preocupar com isso, Sr. Navegador. Por favor, vá em frente.",
  ui_story_5026_50260301_35_dialog_content = "Ahem, então, como escrevi na descrição do trabalho...",
  ui_story_5026_50260301_36_dialog_content = "Espero que você se junte a mim na patrulha de toda a área, avaliando a gravidade da invasão do Eclipsite e eliminando Eclipsites.",
  ui_story_5026_50260301_37_dialog_content = "Além disso, gostaria que você vivenciasse as tarefas diárias do Cloud Gardens e fizesse sugestões de como gerar renda como profissional.",
  ui_story_5026_50260301_38_dialog_content = "(Bethel escreveu a descrição para mim, e o texto é tão formal! Não estou muito acostumado com isso...)",
  ui_story_5026_50260301_39_dialog_content = "E-então... vou fazer uma breve introdução antes de começarmos a trabalhar.",
  ui_story_5026_50260301_40_dialog_content = "Esta é a área central do Cloud Gardens.",
  ui_story_5026_50260301_41_dialog_content = "Não importa onde você queira visitar, este é o lugar mais conveniente para a inteligência.",
  ui_story_5026_50260301_42_dialog_content = "A torre branca atrás de nós é chamada de Torre Jacinto.",
  ui_story_5026_50260301_43_dialog_content = "Todas essas torres brancas, incluindo a Torre Jacinto, são complexos deixados para trás pelos antigos celestitas.",
  ui_story_5026_50260301_44_dialog_content = "Há também muitos projetos empilhados nas torres, assim como alguns dispositivos que não consegui ativar...",
  ui_story_5026_50260301_45_dialog_content = "Oh? Invenções de celestitas talvez? Você tem projetos de armas?",
  ui_story_5026_50260301_46_dialog_content = "Uh... Eu só descobri plantas de prédios e móveis até agora.",
  ui_story_5026_50260301_47_dialog_content = "PlayerName, você é o único celestita conhecido até agora.",
  ui_story_5026_50260301_48_dialog_content = "Você possui um dirigível gigante e uma misteriosa tecnologia antiga, além de poder aprimorar os Aurorianos para a batalha.",
  ui_story_5026_50260301_49_dialog_content = "Dizem que os celestitas sempre foram gentis e pacíficos...",
  ui_story_5026_50260301_50_dialog_content = "Mas seu sonho não para em reconstruir o Eraveil, não é?",
  ui_story_5026_50260301_51_dialog_content = "(Nina parece ter feito alguma pesquisa sobre mim!)",
  ui_story_5026_50260301_52_dialog_content = "Você parece surpreso.",
  ui_story_5026_50260301_53_dialog_content = "Você é um importante parceiro de negócios, então uma verificação de antecedentes foi essencial.",
  ui_story_5026_50260301_54_dialog_content = "Com isso dito, você está interessado no meu plano de dominação agora?",
  ui_story_5026_50260301_55_dialog_content = "Bom, até agora eu ainda nem resolvi as coisas no Eraveil...",
  ui_story_5026_50260301_56_dialog_content = "A prioridade agora é focar nas tarefas que temos pela frente.",
  ui_story_5026_50260301_57_dialog_content = "Se não houver outras perguntas...",
  ui_story_5026_50260301_58_dialog_content = "Por que não começamos com o plantio de árvores?",
  ui_story_5026_50260301_59_dialog_content = "Então é aqui que você cultiva Árvores Únicas...",
  ui_story_5026_50260301_60_dialog_content = "...Ou bem, qualquer coisa.",
  ui_story_5026_50260301_61_dialog_content = "Talvez sua qualidade única seja que eles podem se tornar invisíveis?",
  ui_story_5026_50260301_62_dialog_content = "O isolado Eraveil de fato tem espécies de plantas muito únicas.",
  ui_story_5026_50260301_63_dialog_content = "Tenho que admitir que nunca cultivei plantas antes. Então, como você pode ver...",
  ui_story_5026_50260301_64_dialog_content = "A maior parte do que foi plantado não germinou, e o que cresceu ficou torto?",
  ui_story_5026_50260301_65_dialog_content = "Ah sim. Mas não pretendo desistir.",
  ui_story_5026_50260301_66_dialog_content = "Vamos apará-los e plantar novas sementes.",
  ui_story_5026_50260301_67_dialog_content = "Parece um trabalho que sujaria as saias...",
  ui_story_5026_50260301_68_dialog_content = "O que é essa coisa que parece uma colher gigante?",
  ui_story_5026_50260301_69_dialog_content = "É uma pá, para remover sujeira. Você nunca viu um antes?",
  ui_story_5026_50260301_70_dialog_content = "Claro que tenho! Já o vi muitas vezes em minhas visitas à fazenda com meu pai!",
  ui_story_5026_50260301_71_dialog_content = "Este só parece diferente dos usados pela minha família!",
  ui_story_5026_50260301_72_dialog_content = "Apenas... Apenas entregue para mim, e deixe-me dar uma boa olhada nisso!",
  ui_story_5026_50260301_73_dialog_content = "Existem tantos tipos de pás? Plantar coisas é muito mais complicado do que eu pensava.",
  ui_story_5026_50260301_74_dialog_content = "Deixe-me ver o que os outros dois estão fazendo.",
  ui_story_5026_50260301_75_dialog_content = "Olá, PlayerName.",
  ui_story_5026_50260301_76_dialog_content = "Sobre a poda da Unique Tree... você prefere o estilo de Lumopolis, ou o do Northland Winter Palace?",
  ui_story_5026_50260301_77_dialog_content = "Ambos são populares em Umbraton, mas nosso Último Caelestita pode ter gostos diferentes.",
  ui_story_5026_50260301_78_dialog_content = "Por favor me perdoe. Eu me adiantei.",
  ui_story_5026_50260301_79_dialog_content = "... Isso é tão extra!",
  ui_story_5026_50260301_80_dialog_content = "<size=37>Eu me pergunto como seria o sabor da fruta de uma Árvore Única?</size>",
  ui_story_5026_50260301_81_dialog_content = "<size=35>Eu ganharia algum poder especial ao comê-lo? Eu cresceria asas e uma cauda?</size>",
  ui_story_5026_50260301_82_dialog_content = "<size=33>Afinal, este é o jardim daquele Enigmático Último Caelestita...</size>",
  ui_story_5026_50260301_83_dialog_content = "<size=40>Aah! Este não é o momento para ponderar sobre essas coisas! Se eu não ajudar o Sr. Minos, eu...</size>",
  ui_story_5026_50260301_84_dialog_content = "<size=33>Mas também não quero fazer algo que deixe a Srta. Nina triste...</size>",
  ui_story_5026_50260301_85_dialog_content = "(Sanae parece estar olhando para o poço na frente dela e murmurando para si mesma...)",
  ui_story_5026_50260301_86_dialog_content = "Hum, Sana...",
  ui_story_5026_50260301_87_dialog_content = "Sim! Este sou eu!",
  ui_story_5026_50260301_88_dialog_content = "Só precisamos de alguns buracos rasos para enterrar as sementes. O buraco que você cavou é profundo o suficiente para me enterrar.",
  ui_story_5026_50260301_89_dialog_content = "Eu acabei de fazer uma escavação leve!",
  ui_story_5026_50260301_90_dialog_content = "Chubb...",
  ui_story_5026_50260301_91_dialog_content = "Caelestita detectada, Chubb!",
  ui_story_5026_50260301_92_dialog_content = "Que som é esse?",
  ui_story_5026_50260301_93_dialog_content = "Esta pá grossa é realmente impressionante, PlayerName.",
  ui_story_5026_50260301_94_dialog_content = "Acabamos de enterrar as sementes da árvore e esfregar a terra com a pá duas vezes...",
  ui_story_5026_50260301_95_dialog_content = "E aqui temos uma Árvore Única falante diante de nós em um piscar de olhos.",
  ui_story_5026_50260301_96_dialog_content = "Oh, esta não é uma Árvore Única. Provavelmente aconteceu de andar para este monte.",
  ui_story_5026_50260301_97_dialog_content = "Eu... eu sabia totalmente que era esse o caso! Como poderia ser uma árvore única?",
  ui_story_5026_50260301_98_dialog_content = "Nós os chamamos de Chubbs. Eles apareceram com Cloud Gardens depois que o Obelisco do Retorno se ergueu.",
  ui_story_5026_50260301_99_dialog_content = "Chubb!",
  ui_story_5026_50260301_100_dialog_content = "São...",
  ui_story_5026_50260301_101_dialog_content = "É tão fofo...!",
  ui_story_5026_50260301_102_dialog_content = "Ahem, quero dizer, o que esse pequenino pode fazer?",
  ui_story_5026_50260301_103_dialog_content = "Pelo que você descreveu, é um residente de Cloud Gardens, como você.",
  ui_story_5026_50260301_104_dialog_content = "Então, além de ser fofo, deve contribuir com algo para este lugar, certo?",
  ui_story_5026_50260301_105_dialog_content = "Chubb...",
  ui_story_5026_50260301_106_dialog_content = "Alguns Chubbs me ensinam coisas sobre Cloud Gardens e me ajudam a cuidar das Unique Trees.",
  ui_story_5026_50260301_107_dialog_content = "Mas a maioria dos Chubbs apenas anda ou cochila aqui.",
  ui_story_5026_50260301_108_dialog_content = "Também não sei muito sobre as especificidades de sua estrutura ou função.",
  ui_story_5026_50260301_109_dialog_content = "Mas apenas vê-los andando me deixa feliz.",
  ui_story_5026_50260301_110_dialog_content = "Bem, alguns dos caras da Rediesel Wrench e Illumina gostam de persegui-los, dizendo coisas sobre desmontá-los para dar uma olhada...",
  ui_story_5026_50260301_111_dialog_content = "Chubb! Nada de desmontar Chubb!",
  ui_story_5026_50260301_112_dialog_content = "É tímido, como um coelho.",
  ui_story_5026_50260301_113_dialog_content = "Uh... Eu só acaricio este pequeno companheiro porque parece com medo. Não é como se eu quisesse acariciá-lo ou algo assim. Não me entenda mal.",
  ui_story_5026_50260301_114_dialog_content = "(Eclipsites apareceram em Cloud Gardens, mas esses Chubbs ainda estão relaxados.)",
  ui_story_5026_50260301_115_dialog_content = "(É porque eles são cabeças de vento, ou como os antigos celestitas, eles simplesmente não veem os eclipsitas como inimigos?)",
  ui_story_5026_50260301_116_dialog_content = "(Relíquias de eras atrás guardam tantos segredos, e não tenho certeza se quero conhecer todos eles...)",
  ui_story_5026_50260301_117_dialog_content = "Chubb?",
  ui_story_5026_50260301_118_dialog_content = "(Deve ser porque eles são cabeças de vento.)",
  ui_story_5026_50260301_119_dialog_content = "Chubb!",
  ui_story_5026_50260301_120_dialog_content = "Outro? Quer que eu coce sua orelha também? Bem, não posso dizer não a isso.",
  ui_story_5026_50260301_121_dialog_content = "Então, se este se chama Chubb, e o outro?",
  ui_story_5026_50260301_122_dialog_content = "Huh? Também é chamado Chubb.",
  ui_story_5026_50260301_123_dialog_content = "Mas eles parecem diferentes. Observe o formato de seus olhos e a curva de suas bocas quando sorriem!",
  ui_story_5026_50260301_124_dialog_content = "Há uma diferença?",
  ui_story_5026_50260301_125_dialog_content = "Que amador...",
  ui_story_5026_50260301_126_dialog_content = "Amador?",
  ui_story_5026_50260301_127_dialog_content = "Ouça, PlayerName.",
  ui_story_5026_50260301_128_dialog_content = "Um dos principais princípios da gestão é conhecer bem seus funcionários.",
  ui_story_5026_50260301_129_dialog_content = "Eu queria te perguntar isso desde antes... Onde está sua lista de funcionários, seus livros de contas e seu diário de propriedade?",
  ui_story_5026_50260301_130_dialog_content = "O que são todos aqueles?",
  ui_story_5026_50260301_131_dialog_content = "Você nem sabe o que é uma lista de funcionários?",
  ui_story_5026_50260301_132_dialog_content = "Sinto que estaria insultando sua inteligência se lhe desse uma explicação, mas posso começar do básico.",
  ui_story_5026_50260301_133_dialog_content = "Espere, acho que sinto algo por perto... Isso é...",
  ui_story_5026_50260301_134_dialog_content = "Aaaaaah!",
  ui_story_5026_50260301_135_dialog_content = "N-E agora?!",
  ui_story_5026_50260301_136_dialog_content = "<anim type=Shake>Graagh!</anim>",
  ui_story_5026_50260301_137_dialog_content = "Eu só cutuquei os arbustos um pouco...",
  ui_story_5026_50260301_138_dialog_content = "Como exatamente você define \"um pouco\"?!",
  ui_story_5026_50260402_1_dialog_content = "<anim type=Shake>Gah...</anim>",
  ui_story_5026_50260402_2_dialog_content = "Hmph. Fácil.",
  ui_story_5026_50260402_3_dialog_content = "Sanae, PlayerName, você está bem?",
  ui_story_5026_50260402_4_dialog_content = "E-eles pularam dos arbustos de repente e me assustaram.",
  ui_story_5026_50260402_5_dialog_content = "Isso é uma surpresa. Nina, você é realmente habilidosa em combate.",
  ui_story_5026_50260402_6_dialog_content = "Hmph, pelo menos você pode dizer.",
  ui_story_5026_50260402_7_dialog_content = "Sua habilidade psíquica também é muito especial, permitindo que você veja rastros de luz. Isso me deu uma nova inspiração de design.",
  ui_story_5026_50260402_8_dialog_content = "Espere um segundo... O que você quis dizer com \"surpresa\"? Você está me subestimando?",
  ui_story_5026_50260402_9_dialog_content = "Porque você não se parece com alguém que passa muito tempo brandindo armas por aí...",
  ui_story_5026_50260402_10_dialog_content = "Mas você está certo. Desculpe, eu não deveria ter feito suposições sobre você com base nas primeiras impressões.",
  ui_story_5026_50260402_11_dialog_content = "Graças a você, nos livramos dos inimigos e esta área agora está completamente livre de Darkflow.",
  ui_story_5026_50260402_12_dialog_content = "Obrigado, Nina.",
  ui_story_5026_50260402_13_dialog_content = "Th-Não há necessidade de ser tão formal, e...",
  ui_story_5026_50260402_14_dialog_content = "E também não há necessidade de chegar tão perto!",
  ui_story_5026_50260402_15_dialog_content = "(Você é o único que chegou perto!)",
  ui_story_5026_50260402_16_dialog_content = "<size=33>Ele é o único que o tio Istvan tem vigiado de perto... Não posso baixar a guarda.</size>",
  ui_story_5026_50260402_17_dialog_content = "E você está certo. Como senhora...",
  ui_story_5026_50260402_18_dialog_content = "... O que eles dizem mesmo? Oh, como uma dama, eu deveria ser \"mais elegante e digna\" e não deveria \"andar por aí com armas\".",
  ui_story_5026_50260402_19_dialog_content = "Sem mencionar que prefiro criar armas do que empunhá-las.",
  ui_story_5026_50260402_20_dialog_content = "Quem sabe o que essas nobres julgadoras diriam se descobrissem isso.",
  ui_story_5026_50260402_21_dialog_content = "Nobres?",
  ui_story_5026_50260402_22_dialog_content = "N-Nada! Eliminar Eclipsites faz parte do meu trabalho, eu estava apenas sendo um bom funcionário!",
  ui_story_5026_50260402_23_dialog_content = "Além disso, este é apenas o primeiro passo para consertar Cloud Gardens - apenas sente-se e me veja trabalhar em toda a minha glória!",
  ui_story_5026_50260402_24_dialog_content = "Ah, falando nisso.",
  ui_story_5026_50260402_25_dialog_content = "Minos parece ter terminado todo o trabalho de plantio enquanto conversávamos sobre as diferenças da Chubb.",
  ui_story_5026_50260402_26_dialog_content = "Hã?",
  ui_story_5026_50260402_27_dialog_content = "Ele afrouxou o solo, semeou as sementes, regou-as e fertilizou-as...",
  ui_story_5026_50260402_28_dialog_content = "Ele também colocou placas de sinalização para cada lote de terra e os cercou com flores que complementam a cor das árvores.",
  ui_story_5026_50260402_29_dialog_content = "Chubb também vê, Chubb!",
  ui_story_5026_50260402_30_dialog_content = "Incrível, Chubb!",
  ui_story_5026_50260402_31_dialog_content = "Você me lisonjeia, Sr. Navegador... e querido Chubbs.",
  ui_story_5026_50260402_32_dialog_content = "Por favor, permita-me lembrá-lo, Mestre dos Jardins das Nuvens, que é muito cedo para se sentir seguro sobre o problema do Eclipsite.",
  ui_story_5026_50260402_33_dialog_content = "Acabei de ver uma sombra escura que suspeitei ser um Eclipsite entrando naqueles prédios à distância.",
  ui_story_5026_50260402_34_dialog_content = "Vou em frente e investigar, só para garantir. Por favor, dê-me licença.",
  ui_story_5026_50260402_35_dialog_content = "Uau, ele saiu tão rápido!",
  ui_story_5026_50260402_36_dialog_content = "Acabei de perder uma rodada. Não posso ficar para trás novamente.",
  ui_story_5026_50260402_37_dialog_content = "Sana, vamos!",
  ui_story_5026_50260402_38_dialog_content = "Nós realmente temos alguma chance contra o Sr. Minos...?",
  ui_story_5026_50260402_39_dialog_content = "Parece que eles estão mais preocupados com a segurança de Cloud Gardens do que eu...",
  ui_story_5026_50260402_40_dialog_content = "Essa é a dedicação de contrato pela qual os Umbratons são conhecidos?",
  ui_story_5026_50260501_1_dialog_content = "O que é isto? Não há nenhum Eclipsite em qualquer lugar!",
  ui_story_5026_50260501_2_dialog_content = "Minos já lidou com isso?",
  ui_story_5026_50260501_3_dialog_content = "Eu também não sinto nenhum Darkflow. Ainda assim, não devemos baixar a guarda.",
  ui_story_5026_50260501_4_dialog_content = "Esta grande clareira à nossa frente deve ser segura, pelo menos.",
  ui_story_5026_50260501_5_dialog_content = "Este lugar parece meio familiar...",
  ui_story_5026_50260501_6_dialog_content = "Obviamente. Não importa em que direção você olhe aqui, é apenas o mesmo campo gramado se estendendo para fora.",
  ui_story_5026_50260501_7_dialog_content = "Oh, certo! Eu fui em uma caça ao tesouro aqui perto antes, com Vice!",
  ui_story_5026_50260501_8_dialog_content = "Ouvi dizer que as pessoas nas áreas rurais usarão esses métodos para atrair aventureiros que sonham com riquezas fáceis.",
  ui_story_5026_50260501_9_dialog_content = "Não é uma má forma de estimular a economia local, mas...",
  ui_story_5026_50260501_10_dialog_content = "Isso parece apenas um campo vazio. Você pode realmente encontrar tesouros aqui?",
  ui_story_5026_50260501_11_dialog_content = "Hã, bom...",
  ui_story_5026_50260501_12_dialog_content = "<size=45>Uaaau!</size>",
  ui_story_5026_50260501_13_dialog_content = "A-ahn?!",
  ui_story_5026_50260501_14_dialog_content = "O que me fez tropeçar... uma pedra?",
  ui_story_5026_50260501_15_dialog_content = "Tesouro encontrado! Chubb!",
  ui_story_5026_50260501_16_dialog_content = "Waah, estou tão tonto... O Chubb parece ter se multiplicado...",
  ui_story_5026_50260501_17_dialog_content = "Há realmente muitos Chubbs, Chubb!",
  ui_story_5026_50260501_18_dialog_content = "Owie, owie, vá embora! Chubb!",
  ui_story_5026_50260501_19_dialog_content = "Estou esmagado, Chubb...",
  ui_story_5026_50260501_20_dialog_content = "Sanae sempre parece se meter em situações. Devo considerar isso azarado, ou sortudo...?",
  ui_story_5026_50260501_21_dialog_content = "Nina? O que é isso? Você gostaria de cavar também?",
  ui_story_5026_50260501_22_dialog_content = "Eu realmente não quero.",
  ui_story_5026_50260501_23_dialog_content = "Meu vestido vai ficar manchado de tanta sujeira. Esse vestido é meu último trabalho...",
  ui_story_5026_50260501_24_dialog_content = "(Ela continua olhando para a ferramenta na minha mão...)",
  ui_story_5026_50260501_25_dialog_content = "Você deveria tentar. Aqui, você pode emprestar isso.",
  ui_story_5026_50260501_26_dialog_content = "Hum... S-Já que você insiste, e isso faz parte dos deveres diários do Cloud Gardens, vou tentar.",
  ui_story_5026_50260501_27_dialog_content = "Mas você pode precisar se mover mais rápido.",
  ui_story_5026_50260501_28_dialog_content = "Olhe ali. De alguma forma, Minos já tem um estoque empilhado aos seus pés.",
  ui_story_5026_50260501_29_dialog_content = "Até os Chubbs parecem impressionados.",
  ui_story_5026_50260501_30_dialog_content = "(Hein? Espere...)",
  ui_story_5026_50260501_31_dialog_content = "(Esses caras já pularam ao meu redor com tanta ansiedade e felicidade antes?)",
  ui_story_5026_50260501_32_dialog_content = "Eu já sabia, mas ele realmente é bom em tudo... É tão injusto!",
  ui_story_5026_50260501_33_dialog_content = "Sim, eu me pergunto como ele fez isso? Eu estava tão focado em assistir Sanae que não prestei atenção no que ele estava fazendo...",
  ui_story_5026_50260501_34_dialog_content = "Ei, você não tem ferramentas melhores para caçar tesouros?",
  ui_story_5026_50260501_35_dialog_content = "Existem algumas outras ferramentas ao lado do moinho de vento lá.",
  ui_story_5026_50260501_36_dialog_content = "Espere, acho que eles estão no armazém ao lado do moinho de vento... mas esse lugar não é limpo há muito tempo.",
  ui_story_5026_50260501_37_dialog_content = "Tsk. Isso não vai funcionar.",
  ui_story_5026_50260501_38_dialog_content = "Como o mestre de Cloud Gardens, você deve conhecer sua propriedade como a palma da sua mão!",
  ui_story_5026_50260501_39_dialog_content = "De qualquer forma, eu mesmo vou dar uma olhada.",
  ui_story_5026_50260501_40_dialog_content = "Ah, Nina! Espere por mim!",
  ui_story_5026_50260501_41_dialog_content = "<color=#e8d9bb>Jardins da Nuvem: Sala de Ferramentas</color>",
  ui_story_5026_50260501_42_dialog_content = "Eca! Está tão empoeirado aqui!",
  ui_story_5026_50260501_43_dialog_content = "Há muitos móveis semi-montados. Essas são todas as obras-primas criadas pelo Caelestita?",
  ui_story_5026_50260501_44_dialog_content = "eu não acertei PlayerName ser tão trabalhador.",
  ui_story_5026_50260501_45_dialog_content = "Sua escassez os tornaria valiosos. Se fossem enviados para a casa de leilões em Umbraton como obras de arte de Caelestite, provavelmente alcançariam bons preços.",
  ui_story_5026_50260501_46_dialog_content = "E eles poderiam ser bem embalados, até mesmo exibidos em uma exposição...",
  ui_story_5026_50260501_47_dialog_content = "Não. Agora não é hora de pensar nessas coisas.",
  ui_story_5026_50260501_48_dialog_content = "Ferramentas... Onde estão as ferramentas? Está muito escuro aqui...",
  ui_story_5026_50260501_49_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5026_50260501_50_dialog_content = "<size=45>Huh? Ahh!</size>",
  ui_story_5026_50260501_51_dialog_content = "Era apenas o vento. Eu sabia...",
  ui_story_5026_50260501_52_dialog_content = "<color=#e8d9bb>Clam...</color>",
  ui_story_5026_50260501_53_dialog_content = "<size=45>Huh?!</size>",
  ui_story_5026_50260501_54_dialog_content = "Deve ser um Chubb escondido atrás dos móveis...",
  ui_story_5026_50260501_55_dialog_content = "D-Não se esconda no escuro... Saia!",
  ui_story_5026_50260501_56_dialog_content = "Eu não tenho medo nenhum. Nem um pouco...",
  ui_story_5026_50260501_57_dialog_content = "<size=45>Aaaaah!</size>",
  ui_story_5026_50260501_58_dialog_content = "<anim type=Shake><size=50>Graaaah!</size></anim>",
  ui_story_5026_50260501_59_dialog_content = "Seriamente? Então não era um fantasma...",
  ui_story_5026_50260501_60_dialog_content = "Como ousa um mero Eclipsite me assustar!",
  ui_story_5026_50260502_1_dialog_content = "Você está bem, Nina?",
  ui_story_5026_50260502_2_dialog_content = "Pensei ter ouvido um grito mais cedo.",
  ui_story_5026_50260502_3_dialog_content = "Y-Você ouviu errado! T-Este armazém não é escuro, nem assustador!",
  ui_story_5026_50260502_4_dialog_content = "Foram apenas alguns Eclipsites, mas eu lidei com eles facilmente!",
  ui_story_5026_50260502_5_dialog_content = "Que bom que você está bem. Encontrou a ferramenta certa?",
  ui_story_5026_50260502_6_dialog_content = "Enquanto você estava ocupado procurando ferramentas, Minos, ele... ele já virou tudo do avesso.",
  ui_story_5026_50260502_7_dialog_content = "O quê?!",
  ui_story_5026_50260502_8_dialog_content = "Ele está com os Chubbs agora, restaurando a grama do jeito que era. Ele regou e até contou o número de minhocas...",
  ui_story_5026_50260502_9_dialog_content = "Eu vejo. É assim que é ter Minos como oponente.",
  ui_story_5026_50260502_10_dialog_content = "Me enganar para comer mais vegetais e me impedir de pregar peças na governanta eram apenas brincadeira de criança.",
  ui_story_5026_50260502_11_dialog_content = "Você e Minos se conhecem há muito tempo?",
  ui_story_5026_50260502_12_dialog_content = "Sim, muito tempo. E eu o tolerei por um longo tempo também.",
  ui_story_5026_50260502_13_dialog_content = "Estou farto dele e do pai me tratarem como uma criança.",
  ui_story_5026_50260502_14_dialog_content = "Ok, vamos para a próxima rodada do teste!",
  ui_story_5026_50260502_15_dialog_content = "A terceira vez é o charme. Não vou perder para Minos novamente.",
  ui_story_5026_50260502_16_dialog_content = "Em seguida, vamos procurar minério.",
  ui_story_5026_50260502_17_dialog_content = "Huh... Cloud Gardens tem minérios locais especiais?",
  ui_story_5026_50260502_18_dialog_content = "Minha família, quero dizer, meus parceiros de negócios, a família Andersen, lida com metade dos minerais da Umbraton.",
  ui_story_5026_50260502_19_dialog_content = "Se eu encontrar um depósito de minério raro aqui, aposto que impressionaria a cabeça da família, certo?",
  ui_story_5026_50260502_20_dialog_content = "Metade dos minerais? Esta família Andersen parece realmente impressionante.",
  ui_story_5026_50260502_21_dialog_content = "Quem sabe? Eu só tenho uma relação comercial com eles!",
  ui_story_5026_50260502_22_dialog_content = "O que me preocupa mais é como os minerais podem ser usados, especialmente as gemas.",
  ui_story_5026_50260502_23_dialog_content = "O processo de selecionar, avaliar, enviá-los para serem cortados, definir—",
  ui_story_5026_50260502_24_dialog_content = "Em seguida, incorpore pessoalmente cada gema como parte de uma arma, peça de joalheria ou roupa.",
  ui_story_5026_50260502_25_dialog_content = "Você pode projetar tantas coisas? Você é incrível, Nina.",
  ui_story_5026_50260502_26_dialog_content = "Heheh, meus trabalhos são muito populares em Umbraton...",
  ui_story_5026_50260502_27_dialog_content = "...",
  ui_story_5026_50260502_28_dialog_content = "<size=33>... Mas aprendi recentemente que essa popularidade pode não resultar de minhas próprias habilidades.</size>",
  ui_story_5026_50260502_29_dialog_content = "Por quê?",
  ui_story_5026_50260502_30_dialog_content = "Nada. Eu vi um monte de peças de mobiliário no armazém. Você fez aqueles?",
  ui_story_5026_50260502_31_dialog_content = "Sim. Sou apenas um iniciante, mas recentemente descobri o prazer em fazer móveis e construir prédios.",
  ui_story_5026_50260502_32_dialog_content = "Oh? Então você desenhou todos os móveis e estruturas que eu vi em Cloud Gardens?",
  ui_story_5026_50260502_33_dialog_content = "Ah... Bem, acabei de encontrar plantas em várias partes ao redor da área de antigas estruturas celestitas e restaurei as originais.",
  ui_story_5026_50260502_34_dialog_content = "Qual é a graça de copiar designs do passado?",
  ui_story_5026_50260502_35_dialog_content = "Quando você coloca assim, eu...",
  ui_story_5026_50260502_36_dialog_content = "Eu estava fora de linha.",
  ui_story_5026_50260502_37_dialog_content = "Hã?",
  ui_story_5026_50260502_38_dialog_content = "Você tem suas próprias razões. Eu não deveria criticar seus sentimentos.",
  ui_story_5026_50260502_39_dialog_content = "Não.",
  ui_story_5026_50260502_40_dialog_content = "Sua pergunta me faz pensar seriamente pela primeira vez sobre por que restaurar as coisas me deixa feliz.",
  ui_story_5026_50260502_41_dialog_content = "Por quê?",
  ui_story_5026_50260502_42_dialog_content = "Parece que desta forma, eu seria capaz de recriar alguns dos cenários que foram perdidos no tempo e na guerra...",
  ui_story_5026_50260502_43_dialog_content = "E é quase como se isso afastasse a solidão.",
  ui_story_5026_50260502_44_dialog_content = "... Você não é bem o que eu imaginava, PlayerName.",
  ui_story_5026_50260502_45_dialog_content = "Como assim?",
  ui_story_5026_50260502_46_dialog_content = "Sanae muitas vezes me fala sobre uma certa coluna no Umbraton Daily que afirma detalhar com precisão a vida de PlayerName o celestita.",
  ui_story_5026_50260502_47_dialog_content = "O pai diz que o jornal imprime mais bobagens em suas páginas do que as falsificações do Nightmist Market.",
  ui_story_5026_50260502_48_dialog_content = "Alguém realmente escreve uma coluna sobre mim?",
  ui_story_5026_50260502_49_dialog_content = "Você é mais popular do que pensa, sabe.",
  ui_story_5026_50260502_50_dialog_content = "Lembro-me do título do primeiro artigo. \"Chocante! Um adolescente volta à vida depois de ser enterrado por dezessete anos!\"",
  ui_story_5026_50260502_51_dialog_content = "Se você estiver interessado, Sanae guarda recortes do artigo de cada semana sem falhas e os coloca em um álbum de recortes...",
  ui_story_5026_50260502_52_dialog_content = "Ela também comprou o livro que é uma publicação de todos os artigos em um volume.",
  ui_story_5026_50260502_53_dialog_content = "... Por favor, diga-me como fazê-los parar de escrever.",
  ui_story_5026_50260502_54_dialog_content = "Interessante. Você está tentando assumir o controle da narrativa?",
  ui_story_5026_50260502_55_dialog_content = "De fato, como um novo poder que está apenas surgindo, é importante que você também gerencie sua imagem.",
  ui_story_5026_50260502_56_dialog_content = "Não, só acho constrangedor...",
  ui_story_5026_50260502_57_dialog_content = "Você é um pedaço de carne brilhante para os tablóides. Melhor tomar cuidado e manter seus segredos por perto.",
  ui_story_5026_50260502_58_dialog_content = "Vou tomar cuidado...",
  ui_story_5026_50260502_59_dialog_content = "Oh não! Eu não sabia que estávamos conversando há tanto tempo!",
  ui_story_5026_50260502_60_dialog_content = "Sanae e Minos provavelmente ainda estão esperando. É melhor partirmos agora para os minérios!",
  ui_story_5026_50260502_61_dialog_content = "Espero que não encontremos mais Eclipsitos em nosso caminho para lá.",
  ui_story_5026_50260702_1_dialog_content = "De onde vieram todos esses Eclipsitas em primeiro lugar?",
  ui_story_5026_50260702_2_dialog_content = "A presença deles é realmente tão surpreendente para você? É normal ser constantemente incomodado por Eclipsitas aqui neste continente.",
  ui_story_5026_50260702_3_dialog_content = "Eu estava morando no Colossus antes disso, então nunca experimentei isso...",
  ui_story_5026_50260702_4_dialog_content = "Escusado será dizer para as fazendas, florestas e ranchos ao redor de Umbraton. Até os pescadores ao longo do rio Gold sabem disso.",
  ui_story_5026_50260702_5_dialog_content = "Tempos de paz são escassos e preciosos.",
  ui_story_5026_50260702_6_dialog_content = "Você não pode voar no céu nem se esconder no subsolo aqui, e também não está sob a proteção de nenhum auroriano poderoso.",
  ui_story_5026_50260702_7_dialog_content = "Então, pelo contrário, não vejo como Cloud Gardens poderia estar isento de invasões de Eclipsite.",
  ui_story_5026_50260702_8_dialog_content = "A menos que os celestitas e os aurorianos sejam decisivamente diferentes na forma como lidamos com os eclipsitas?",
  ui_story_5026_50260702_9_dialog_content = "(Que pergunta aguda!)",
  ui_story_5026_50260702_10_dialog_content = "Ouvi dizer que os Caelestites não podiam usar Luminatics para lutar.",
  ui_story_5026_50260702_11_dialog_content = "Você também não pode usar Luminatics para manipular ferramentas, como estou fazendo agora, então não preciso realizar trabalho físico sozinho.",
  ui_story_5026_50260702_12_dialog_content = "Parece que você precisa balançar sua picareta três ou quatro vezes apenas para retirar um pedaço de minério...",
  ui_story_5026_50260702_13_dialog_content = "<color=#e8d9bb>Bam!</color>",
  ui_story_5026_50260702_14_dialog_content = "Ah! Isso te machucou? Desculpe!",
  ui_story_5026_50260702_15_dialog_content = "<anim type=Shake>Chubb...</anim>",
  ui_story_5026_50260702_16_dialog_content = "Mesmo sabendo lidar com armas muito bem, demoro algum tempo para me acostumar com o peso dessas ferramentas e como elas são usadas...",
  ui_story_5026_50260702_17_dialog_content = "Onde estávamos antes, PlayerName?",
  ui_story_5026_50260702_18_dialog_content = "Ah sim, o que eu aprendi sobre as habilidades dos celestitas é que elas não são tão úteis para defender territórios...",
  ui_story_5026_50260702_19_dialog_content = "Mas os celestitas podem ordenar que os aurorianos lutem com eficiência, então seus ancestrais empregaram os aurorianos como seus guardas?",
  ui_story_5026_50260702_20_dialog_content = "Se houvesse comunicação frequente entre as duas raças, deveria haver mais informações na biblioteca do Pai que—",
  ui_story_5026_50260702_21_dialog_content = "<size=45>Uau!</size>",
  ui_story_5026_50260702_22_dialog_content = "O-o que aconteceu? Eles estão ficando juntos porque querem se vingar de seu amigo?",
  ui_story_5026_50260702_23_option_content = "Não, não acho que seja isso.",
  ui_story_5026_50260702_24_option_content = "Devo tentar usar minha habilidade?",
  ui_story_5026_50260702_25_dialog_content = "(Falando nisso, nunca pensei no que se passa na cabeça dos Chubbs.)",
  ui_story_5026_50260702_26_dialog_content = "Ajude Chubb!",
  ui_story_5026_50260702_27_dialog_content = "Vocês... Estão me ajudando a separar os minérios que extraímos?",
  ui_story_5026_50260702_28_dialog_content = "Chubb!",
  ui_story_5026_50260702_29_dialog_content = "Ok, fique com este. Deve ser de ferro, que pode ser usado para fazer ferramentas.",
  ui_story_5026_50260702_30_dialog_content = "Há quartzo também, mas a finura pode ser um problema, então só pode ser usado como material de construção.",
  ui_story_5026_50260702_31_dialog_content = "Ah, isso pode ser uma pedra preciosa bruta! Seja gentil com isso!",
  ui_story_5026_50260702_32_dialog_content = "Entendi, Chubb!",
  ui_story_5026_50260702_33_dialog_content = "Que adorável... Ahem... quero dizer, criaturas maravilhosas.",
  ui_story_5026_50260702_34_dialog_content = "Parece que o Cloud Gardens tem seu próprio sistema exclusivo para segurança e produção.",
  ui_story_5026_50260702_35_dialog_content = "(Sistema único? Ainda não tive tempo para pensar sobre isso antes.)",
  ui_story_5026_50260702_36_dialog_content = "(Minha primeira impressão de Nina foi que ela não era bem versada em assuntos mundanos, e seu plano de dominação também parecia muito forçado.)",
  ui_story_5026_50260702_37_dialog_content = "(Mas não há dúvida sobre seu profissionalismo quando se trata de negócios!)",
  ui_story_5026_50260702_38_dialog_content = "(Enquanto isso eu... eu nem sei muito sobre esse lugar que chamo de lar.)",
  ui_story_5026_50260702_39_dialog_content = "(Sou eu que estou em liberdade condicional aqui, certo? Será que vou conseguir passar?)",
  ui_story_5026_50260702_40_dialog_content = "Você parece estar muito interessado nas operações da Cloud Gardens.",
  ui_story_5026_50260702_41_dialog_content = "É aqui que o plano de dominação mundial que eu criei começa, afinal. É natural aprender o máximo possível sobre isso, certo?",
  ui_story_5026_50260702_42_dialog_content = "Você parece ter a mesma idade que eu, mas você é realmente impressionante.",
  ui_story_5026_50260702_43_dialog_content = "O-o quê? Você não tem nada a ganhar me lisonjeando assim.",
  ui_story_5026_50260702_44_dialog_content = "Em seguida, é hora de registrar nossos resultados.",
  ui_story_5026_50260702_45_dialog_content = "Consegui bastante. Não vou perder para Minos desta vez, certo?",
  ui_story_5026_50260702_46_dialog_content = "Incrível, Chubb!",
  ui_story_5026_50260702_47_dialog_content = "O mestre também é incrível, Chubb!",
  ui_story_5026_50260702_48_dialog_content = "Mestre?",
  ui_story_5026_50260702_49_dialog_content = "Há uma pilha de minérios ainda maior ao lado da sua. São estes o que Minos extraiu?",
  ui_story_5026_50260702_50_dialog_content = "E-quando vocês foram subornados por Minos?!",
  ui_story_5026_50260702_51_dialog_content = "Hum... Senhorita...",
  ui_story_5026_50260702_52_dialog_content = "Quero dizer, Nina!",
  ui_story_5026_50260702_53_dialog_content = "Como está do seu lado? Concordamos em confirmar a localização de um depósito de minério, mas não posso mais cavar. E eu...",
  ui_story_5026_50260702_54_dialog_content = "... Estou com tanta fome!",
  ui_story_5026_50260702_55_dialog_content = "Quem falou agora?",
  ui_story_5026_50260702_56_dialog_content = "<size=45>Aaah! M-Mana!</size>",
  ui_story_5026_50260702_57_dialog_content = "Sem trabalho, sem comida, eu entendo... Mas não tomamos nem um gole de água depois de horas cavando?",
  ui_story_5026_50260702_58_dialog_content = "Mesmo a mina em que trabalhamos antes na calada da noite sem a permissão do Shadowlord não era tão exploradora!",
  ui_story_5026_50260702_59_dialog_content = "Mana! Shh!",
  ui_story_5026_50260702_60_dialog_content = "Desculpe! Eu nem levei isso em consideração. Vou pegar um pouco de água para você agora mesmo!",
  ui_story_5026_50260702_61_dialog_content = "(Huh? Bonecas também precisam de água?)",
  ui_story_5026_50260702_62_dialog_content = "(Eu estava tão preocupada em ser repreendida que pedi desculpas a uma boneca sem perceber...)",
  ui_story_5026_50260702_63_dialog_content = "(Não, não, não, mais importante...)",
  ui_story_5026_50260702_64_dialog_content = "<size=45>Falou?!</size>",
  ui_story_5026_50260702_65_dialog_content = "Estou alucinando porque estou tão cansado?",
  ui_story_5026_50260702_66_dialog_content = "Por que não fazer uma pausa, Sr. Navegador?",
  ui_story_5026_50260702_67_dialog_content = "Todos, por favor, sentem-se aqui.",
  ui_story_5026_50260702_68_dialog_content = "De onde vieram essas mesas e cadeiras?",
  ui_story_5026_50260702_69_dialog_content = "E de onde vieram esses lanches?",
  ui_story_5026_50260702_70_dialog_content = "Peguei sua cozinha emprestada com a ajuda de Chubbs. Os lanches estão do seu agrado?",
  ui_story_5026_50260702_71_dialog_content = "Eles são tão bons...",
  ui_story_5026_50260702_72_dialog_content = "(Waah, eu sabia. A comida ruim em Cloud Gardens não era por causa da cozinha.)",
  ui_story_5026_50260702_73_dialog_content = "Sr. Navigator, eu te assustei antes?",
  ui_story_5026_50260702_74_dialog_content = "Este boneco é Manae. Às vezes ela abre a boca do nada e diz coisas desconfortáveis.",
  ui_story_5026_50260702_75_dialog_content = "Eu sei que ela está apenas cuidando de mim, mas...",
  ui_story_5026_50260702_76_dialog_content = "Sanae, o chá está transbordando.",
  ui_story_5026_50260702_77_dialog_content = "<size=45>S-Desculpe!</size>",
  ui_story_5026_50260702_78_dialog_content = "Dois cubos de açúcar, mexidos dez vezes no sentido horário e três vezes no sentido anti-horário. Aqui, senhorita Nina.",
  ui_story_5026_50260702_79_dialog_content = "Uh-hum.",
  ui_story_5026_50260702_80_dialog_content = "(Nina parece acostumada com isso...)",
  ui_story_5026_50260702_81_dialog_content = "(Está tudo bem para mim ficar relaxado assim quando Eclipsites estão correndo por todo Cloud Gardens?)",
  ui_story_5026_50260702_82_dialog_content = "(Mas de qualquer forma, não é como se o estresse resolvesse alguma coisa.)",
  ui_story_5026_50260702_83_dialog_content = "(Como Nina perguntou anteriormente, como os celestitas se defendiam contra intrusos no passado?)",
  ui_story_5026_50260702_84_dialog_content = "(Contratar aurorianos como guarda-costas era obviamente impossível.)",
  ui_story_5026_50260702_85_dialog_content = "(Se o Obelisco do Retorno era o único meio de defesa aqui, o que devo fazer agora que ele ficou em silêncio?)",
  ui_story_5026_50260702_86_dialog_content = "(Mesmo que existam outras armas deixadas pelos antigos celestitas, seus inimigos poderiam—)",
  ui_story_5026_50260702_87_dialog_content = "No que você está pensando tanto?",
  ui_story_5026_50260702_88_dialog_content = "N-Nada!",
  ui_story_5026_50260702_89_dialog_content = "A hora do chá é uma hora sagrada que não deve ser invadida. Não pense em coisas desnecessárias.",
  ui_story_5026_50260702_90_dialog_content = "É importante permitir-se desacelerar de vez em quando.",
  ui_story_5026_50260702_91_dialog_content = "Mas se você tiver alguma dúvida sobre o que fizemos até agora, sinta-se à vontade para nos dizer.",
  ui_story_5026_50260702_92_dialog_content = "Não é realmente dúvida, mas estou curioso sobre algo.",
  ui_story_5026_50260702_93_dialog_content = "Qual é a relação entre vocês três e por que você se candidatou ao cargo de gerente na Cloud Gardens?",
  ui_story_5026_50260702_94_dialog_content = "Você não parece estar acostumado com trabalho físico.",
  ui_story_5026_50260702_95_dialog_content = "Y-Você pode dizer!?",
  ui_story_5026_50260702_96_dialog_content = "E Sanae não é meticulosa o suficiente para ser boa no trabalho doméstico.",
  ui_story_5026_50260702_97_dialog_content = "M-Mas eu... <size=45>Ahhhh! Os copos!</size>",
  ui_story_5026_50260702_98_dialog_content = "Minos, por outro lado... é impecável ao ponto de ser horrível. Você pode obviamente encontrar um emprego melhor.",
  ui_story_5026_50260702_99_dialog_content = "Obrigado pelo elogio, mas sou apenas um simples mordomo.",
  ui_story_5026_50260702_100_dialog_content = "Não entenda mal. Não estou criticando nenhum de vocês!",
  ui_story_5026_50260702_101_dialog_content = "Tenho certeza que deve haver uma razão para vocês terem seus segredos.",
  ui_story_5026_50260702_102_dialog_content = "Sem você, não teria como lidar com tantos Eclipses.",
  ui_story_5026_50260702_103_dialog_content = "E vocês me fizeram perceber que Cloud Gardens precisa de muito mais trabalho.",
  ui_story_5026_50260702_104_dialog_content = "Minos me chama de Mestre dos Jardins das Nuvens, e os Chubbs me chamam de Mestre também...",
  ui_story_5026_50260702_105_dialog_content = "Mas eu realmente mereço esse título?",
  ui_story_5026_50260702_105X1_dialog_content = "Em vez de perder tempo duvidando de si mesmo, você deve pensar no que pode fazer para se tornar merecedor do título.",
  ui_story_5026_50260702_105X2_dialog_content = "Pelo menos, é o que eu faria.",
  ui_story_5026_50260702_105X3_dialog_content = "Mas ao contrário da minha sugestão, acho que o que você precisa mais agora é...",
  ui_story_5026_50260702_106_dialog_content = "...",
  ui_story_5026_50260702_107_dialog_content = "PlayerName, existe algum lugar que você goste particularmente em Cloud Gardens?",
  ui_story_5026_50260702_108_dialog_content = "Quando preciso relaxar, vou pescar.",
  ui_story_5026_50260702_109_dialog_content = "Mas eu encontrei Eclipsites no meu caminho para lá da última vez...",
  ui_story_5026_50260702_110_dialog_content = "Por que você pergunta, você quer—",
  ui_story_5026_50260702_110X1_dialog_content = "E-Definitivamente não é porque eu quero que você relaxe ou algo assim!",
  ui_story_5026_50260702_111_dialog_content = "Conhecer os hobbies dos meus parceiros de negócios faz parte do trabalho!",
  ui_story_5026_50260702_112_dialog_content = "Agora que você fez suas realizações, termine seu chá e vamos começar.",
  ui_story_5026_50260801_1_dialog_content = "<color=#e8d9bb>Eraveil: Deserto</color>",
  ui_story_5026_50260801_2_dialog_content = "Hmm... Ainda estou um pouco preocupado.",
  ui_story_5026_50260801_3_dialog_content = "Só fiquei sabendo da situação na casa dos Andersen depois de voltar a Umbraton para perguntar por aí...",
  ui_story_5026_50260801_4_dialog_content = "O que anda acontecendo no mundo?",
  ui_story_5026_50260801_5_dialog_content = "Oi! Chegamos ao rio com segurança desta vez!",
  ui_story_5026_50260801_6_dialog_content = "A última vez que vim pescar, Eclipsites apareceram de repente. Não sei o que teria acontecido se Betel não estivesse lá.",
  ui_story_5026_50260801_7_dialog_content = "Eu provavelmente teria me picado em uma folha de grama, considerando o quanto o Spikepest estragou o lugar.",
  ui_story_5026_50260801_8_dialog_content = "Você e Betel são muito próximos?",
  ui_story_5026_50260801_9_dialog_content = "Lutamos lado a lado com Luke dos Mercenários da Chama Branca no incidente da Guilda Leão Azul.",
  ui_story_5026_50260801_10_dialog_content = "Nós nos cruzamos algumas vezes depois. Naquela vez que ela me salvou, ela realmente veio em nome de Sheol e da Guilda Cloudrover.",
  ui_story_5026_50260801_11_dialog_content = "Hmph. Eu vejo.",
  ui_story_5026_50260801_12_dialog_content = "Ela é uma comerciante impressionante. Ela fez um bom trabalho gerenciando a guilda de Istvan.",
  ui_story_5026_50260801_13_dialog_content = "De volta à Dawn Academy, todos também cantaram louvores a Bethel.",
  ui_story_5026_50260801_14_dialog_content = "D-Não pense demais! Não é que eu me importe com o que acontece entre vocês dois!",
  ui_story_5026_50260801_15_dialog_content = "(Então ela se importa.)",
  ui_story_5026_50260801_16_dialog_content = "Você disse que pescar fazia parte de suas tarefas diárias aqui, certo?",
  ui_story_5026_50260801_17_dialog_content = "Se for esse o caso, não pode ser tratado como qualquer atividade casual.",
  ui_story_5026_50260801_18_dialog_content = "Uma vez. Apenas uma vez, eu preciso vencer Minos.",
  ui_story_5026_50260801_19_dialog_content = "No entanto, havia apenas uma vara de pescar, e os Chubbs a deram a Minos.",
  ui_story_5026_50260801_20_dialog_content = "O quê?",
  ui_story_5026_50260801_21_dialog_content = "Eu sei. É um pouco trabalhoso sem uma vara de pescar.",
  ui_story_5026_50260801_22_dialog_content = "O que o torna tão popular entre os Chubbs!?",
  ui_story_5026_50260801_23_dialog_content = "Então é com isso que você realmente se importa...",
  ui_story_5026_50260801_24_dialog_content = "Apenas para equilibrar as chances, eu vou te ensinar a pescar sem vara de pescar.",
  ui_story_5026_50260801_25_dialog_content = "No Extremo Oriente, todos me chamam de o grande \"Mestre Peixinho Dourado\"!",
  ui_story_5026_50260801_26_dialog_content = "Mesmo que eu não tenha as ferramentas que eu tinha lá atrás e os peixes sejam diferentes, bem... eles ainda são peixes, certo?",
  ui_story_5026_50260801_27_dialog_content = "...",
  ui_story_5026_50260801_28_dialog_content = "Sanae, você me disse uma vez que costumava pescar no rio quando era jovem. Que tal você me ensinar?",
  ui_story_5026_50260801_29_dialog_content = "(Ela me ignorou!)",
  ui_story_5026_50260801_30_dialog_content = "Ah... ahaha... ahaha! Acho que vi alguns peixes por lá agora. Irei conferir!",
  ui_story_5026_50260801_31_dialog_content = "PlayerNamese foi...",
  ui_story_5026_50260801_32_dialog_content = "Senhorita Nina, você... Pegar peixe está abaixo de você! Permita-me!",
  ui_story_5026_50260801_33_dialog_content = "Ser capaz de pescar ou não costumava significar a diferença entre a vida e a morte para mim.",
  ui_story_5026_50260801_34_dialog_content = "Mesmo que eu não seja tão bom quanto o renomado PlayerName, ainda vou dar o meu melhor!",
  ui_story_5026_50260801_35_dialog_content = "Você me chamou de \"Senhorita Nina\" de novo, não foi?",
  ui_story_5026_50260801_36_dialog_content = "Ah! S-Desculpe por isso!",
  ui_story_5026_50260801_37_dialog_content = "Não estou preocupado em revelar minha identidade. Se eu não estiver errado, PlayerName realmente não se importa.",
  ui_story_5026_50260801_38_dialog_content = "Ele nunca ouviu falar do Conde Andersen. Eu previ isso.",
  ui_story_5026_50260801_39_dialog_content = "O pai pode possuir muitas terras em Astra, mas para o celestita, ele é um velho qualquer.",
  ui_story_5026_50260801_40_dialog_content = "De alguma forma, isso me deixa feliz.",
  ui_story_5026_50260801_41_dialog_content = "N-Nina...",
  ui_story_5026_50260801_42_dialog_content = "Isso mesmo, Sanae. Eu sou apenas Nina aqui. E... pescar parece divertido.",
  ui_story_5026_50260801_43_dialog_content = "Eu só via pessoas fazendo isso ao lado do Gold River sempre que passava por ele. Estou louca para tentar.",
  ui_story_5026_50260801_44_dialog_content = "U-Um Nina... Seu vestido é um pouco longo para pescar.",
  ui_story_5026_50260801_45_dialog_content = "Está bem. Eu vou segurar.",
  ui_story_5026_50260801_46_dialog_content = "Tudo que você precisa é me dizer como bloquear o alvo, e meus Luminatics farão o resto.",
  ui_story_5026_50260801_47_dialog_content = "Ah! A água está tão fria!",
  ui_story_5026_50260801_48_dialog_content = "As pedras na água são escorregadias. Cuidado onde pisa!",
  ui_story_5026_50260801_49_dialog_content = "Se o Sr. Minos estivesse aqui, ele provavelmente o lembraria de cuidar de seu status e ser elegante.",
  ui_story_5026_50260801_50_dialog_content = "Mas ele parece estar preocupado com outra coisa agora.",
  ui_story_5026_50260801_51_dialog_content = "Deixe-me mostrar-lhe como pescar.",
  ui_story_5026_50260801_52_dialog_content = "Primeiro, fique parado na água, assim como seus pés estão enraizados no leito do rio.",
  ui_story_5026_50260801_53_dialog_content = "Em seguida, observe o movimento do peixe e escolha seu alvo.",
  ui_story_5026_50260801_54_dialog_content = "Ei! Isso é um baiacu ali. É delicioso quando cozido no vapor!",
  ui_story_5026_50260801_55_dialog_content = "Esse peixe-faca daria um belo assado...",
  ui_story_5026_50260801_56_dialog_content = "<size=45>Hehehe... Hahahaha!</size>",
  ui_story_5026_50260801_57_dialog_content = "O-o quê? Oh, me desculpe! Acabei de comer lanches e agora estou...",
  ui_story_5026_50260801_58_dialog_content = "Está bem. Eu só estava pensando, isso é tão você.",
  ui_story_5026_50260801_59_dialog_content = "Você fica bastante tagarela quando encontra algo sobre o qual gosta de falar.",
  ui_story_5026_50260801_60_dialog_content = "Isso é verdade... É estranho?",
  ui_story_5026_50260801_61_dialog_content = "Pelo contrário. Eu acho bem fofo.",
  ui_story_5026_50260801_62_dialog_content = "Hmm... E-onde estávamos agora?",
  ui_story_5026_50260801_63_dialog_content = "Observe os peixes e escolha seu alvo.",
  ui_story_5026_50260801_64_dialog_content = "Certo! Agora, mate quando o peixe ainda estiver desprevenido...",
  ui_story_5026_50260801_65_dialog_content = "<size=45>Agora!</size>",
  ui_story_5026_50260801_66_dialog_content = "Te peguei!",
  ui_story_5026_50260801_67_dialog_content = "Incrível!",
  ui_story_5026_50260801_68_dialog_content = "Hehe...",
  ui_story_5026_50260801_69_dialog_content = "Deixe-me tentar... Uau! É tão escorregadio!",
  ui_story_5026_50260801_70_dialog_content = "Foi embora...",
  ui_story_5026_50260801_71_dialog_content = "É assim que o grande Mestre Peixinho Dourado faz, PlayerName? Estou sem palavras.",
  ui_story_5026_50260801_72_dialog_content = "É mais fácil falar do que fazer! Você tenta!",
  ui_story_5026_50260801_73_dialog_content = "Ah! Apenas observe-me!",
  ui_story_5026_50260801_74_dialog_content = "A senhorita Nina com certeza está se divertindo.",
  ui_story_5026_50260801_75_dialog_content = "Huh? Eu pensei que você estava pescando com Nina, PlayerName?",
  ui_story_5026_50260801_76_dialog_content = "Ela está se divertindo muito com Sanae, então achei melhor deixá-los em paz.",
  ui_story_5026_50260801_77_dialog_content = "Mas por que você voltou? Ei, Sheol rejeitou meu pedido para adiar o pagamento?",
  ui_story_5026_50260801_78_dialog_content = "Não, está indo bem, mas...",
  ui_story_5026_50260801_79_dialog_content = "Sr. Minos, é verdade que o Conde Andersen tem recusado visitas devido a problemas de saúde?",
  ui_story_5026_50260801_80_dialog_content = "Parece que você já ouviu falar, Lady Bethel.",
  ui_story_5026_50260801_81_dialog_content = "...",
  ui_story_5026_50260801_82_dialog_content = "(Minos estava apenas me avaliando? Ou eu estava enganado?)",
  ui_story_5026_50260801_83_dialog_content = "Na verdade, isso aconteceu depois que a senhorita Nina fugiu de casa e disse: \"Eu te odeio, papai!\"...",
  ui_story_5026_50260801_84_dialog_content = "O Mestre cancelou todas as reuniões e se trancou em seu quarto.",
  ui_story_5026_50260801_85_dialog_content = "Espere um minuto. Então, quem está cuidando de todos os assuntos relacionados às suas propriedades e terras agora?",
  ui_story_5026_50260801_86_dialog_content = "Obrigado por sua preocupação, Lady Bethel.",
  ui_story_5026_50260801_87_dialog_content = "Mas para mim, nenhum caso é mais importante do que os dois.",
  ui_story_5026_50260801_88_dialog_content = "Pai! Você enviou pessoas para comprar todas as mercadorias da minha loja?",
  ui_story_5026_50260801_89_dialog_content = "Nina, minha querida, do que você está falando?",
  ui_story_5026_50260801_90_dialog_content = "Você limpou minha loja para fazer parecer que eles eram populares, não é?",
  ui_story_5026_50260801_91_dialog_content = "Na verdade, pensei que o que eu projetei era muito bom... mas agora...",
  ui_story_5026_50260801_92_dialog_content = "Oh, meu querido... Não fique chateado!",
  ui_story_5026_50260801_93_dialog_content = "É meu mal! Eu só quero te dar tudo o que você merece, todas as melhores coisas!",
  ui_story_5026_50260801_94_dialog_content = "Papai, você é sempre assim!",
  ui_story_5026_50260801_95_dialog_content = "Toda vez que eu acho que finalmente consegui algo por conta própria, descubro que você está puxando as cordas nos bastidores!",
  ui_story_5026_50260801_96_dialog_content = "Você acha que sem a sua ajuda, sem o nome Andersen, eu sou totalmente indefeso?!",
  ui_story_5026_50260801_97_dialog_content = "N-Não! Claro que não! Não é assim, Nina!",
  ui_story_5026_50260801_98_dialog_content = "<size=45>Eu te odeio, papai!</size>",
  ui_story_5026_50260801_99_dialog_content = "E foi assim que a dona Nina acabou pegando Sanae e fugindo.",
  ui_story_5026_50260801_100_dialog_content = "Então o Mestre me mandou atrás da Srta. Nina para trazê-la de volta... Mas não contra a vontade dela.",
  ui_story_5026_50260801_101_dialog_content = "(Isso parece uma tarefa difícil.)",
  ui_story_5026_50260801_102_dialog_content = "De jeito nenhum. Faz parte do meu trabalho.",
  ui_story_5026_50260801_103_dialog_content = "(Ele acabou de ler minha mente?)",
  ui_story_5026_50260801_104_dialog_content = "Eu não li sua mente. Por favor, fique à vontade.",
  ui_story_5026_50260801_105_dialog_content = "Então como você sabe o que estou pensando!?",
  ui_story_5026_50260801_106_dialog_content = "Se não se importa que eu diga, Sr. Navegador, você é como um livro aberto.",
  ui_story_5026_50260801_107_dialog_content = "Mas você é diferente de qualquer pessoa que a Srta. Nina já conheceu. Pode ser por isso que ela se abriu para você.",
  ui_story_5026_50260801_108_dialog_content = "Uau, você chama nossas interações atuais como ela se \"abrindo\" para mim?",
  ui_story_5026_50260801_109_dialog_content = "As sombras estão sempre observando, Sr. Navegador. Mais de um, na verdade.",
  ui_story_5026_50260801_110_dialog_content = "Espero que nunca traia a confiança da Srta. Nina.",
  ui_story_5026_50260801_111_dialog_content = "Não se preocupe. Se o pior acontecer...",
  ui_story_5026_50260801_112_dialog_content = "A Sra. Sheol ainda garantiria que, em termos de negócios, conseguir menos negócios pela metade do preço seria a única coisa que você teria que enfrentar.",
  ui_story_5026_50260801_113_dialog_content = "Claro, haveria consequências não relacionadas a questões de negócios também.",
  ui_story_5026_50260801_114_dialog_content = "Não, não, não, não diga mais nada. Ofertas pela metade do preço importam muito para mim!",
  ui_story_5026_50260801_115_dialog_content = "Obrigado pela sua compreensão.",
  ui_story_5026_50260801_116_dialog_content = "No entanto, tenho que deixar algo claro.",
  ui_story_5026_50260801_117_dialog_content = "Para mim, Nina é Nina. Nem seu status nem sua identidade mudariam como eu a vejo.",
  ui_story_5026_50260801_118_dialog_content = "Ela ficaria grata em ouvir você dizer isso... de verdade.",
  ui_story_5026_50260801_119_dialog_content = "Deixa eu te perguntar uma coisa...",
  ui_story_5026_50260801_120_dialog_content = "Se ela ficasse chateada comigo e fugisse gritando: \"PlayerName é um idiota!\"... O que aconteceria então?",
  ui_story_5026_50260801_121_dialog_content = "Você morreria, naturalmente.",
  ui_story_5026_50260801_122_dialog_content = "(Sinto um frio na espinha... tenho certeza que não imaginei!)",
  ui_story_5026_50260801_123_dialog_content = "Isso foi uma piada. Não sou um carrasco, apenas um simples mordomo.",
  ui_story_5026_50260801_124_dialog_content = "(Ele não parece estar brincando!)",
  ui_story_5026_50260801_125_dialog_content = "Foi um prazer conversar com você, Sr. Navegador. Como você gostaria de lidar com o peixe?",
  ui_story_5026_50260801_126_dialog_content = "Nossa, isso é muito! E são todos peixes ornamentais!",
  ui_story_5026_50260801_127_dialog_content = "Já mandei os Chubbs mandarem os comestíveis de volta para a cozinha.",
  ui_story_5026_50260801_128_dialog_content = "Se não for muito incômodo, por favor, coloque esses peixes ornamentais na Fonte da Esperança perto da Torre Jacinto.",
  ui_story_5026_50260801_129_dialog_content = "Como quiser. Agora, por favor, desculpe-me, Lady Bethel, Sr. Navegador.",
  ui_story_5026_50260801_130_dialog_content = "Bethel... Os mordomos em Umbraton são todos assim?",
  ui_story_5026_50260801_131_dialog_content = "Assim como na minha guilda, o Shadowlord também tem subordinados que lidam com coisas diferentes.",
  ui_story_5026_50260801_132_dialog_content = "Você pode conhecer alguns deles. Eles são bons no que fazem e farão o que for preciso.",
  ui_story_5026_50260801_133_dialog_content = "Quanto à Associação Andersen, Minos lida com todos esses \"assuntos\" estranhos.",
  ui_story_5026_50260801_134_dialog_content = "Ele é o melhor dos melhores, não há mordomos como ele.",
  ui_story_5026_50260801_135_dialog_content = "Certo... Obrigado... Betel.",
  ui_story_5026_50260801_136_dialog_content = "(Talvez eu não devesse ter perguntado...)",
  ui_story_5026_50260801_137_dialog_content = "Nina, Nina! O peixe está vindo em sua direção!",
  ui_story_5026_50260801_138_dialog_content = "...",
  ui_story_5026_50260801_139_dialog_content = "Minos, PlayerName, e... Isso é Betel?",
  ui_story_5026_50260801_140_dialog_content = "O que eles estão discutindo entre si?",
  ui_story_5026_50260801_141_dialog_content = "Nina, você está ouvindo?",
  ui_story_5026_50260801_142_dialog_content = "Nina está olhando na direção daqueles três, murmurando para si mesma.",
  ui_story_5026_50260801_143_dialog_content = "Ela provavelmente está preocupada que, se não conseguir vencer Minos, terá que ir para casa com ele.",
  ui_story_5026_50260801_144_dialog_content = "Sanae, já decidiu quem vai ajudar?",
  ui_story_5026_50260801_145_dialog_content = "Eu não vou deixar Nina perder!",
  ui_story_5026_50260801_146_dialog_content = "Mas se você perder este emprego, estará nas ruas novamente.",
  ui_story_5026_50260801_147_dialog_content = "Pare de me dizer isso! Eu vou pegar aquela garoupa, nem você vai me distrair!",
  ui_story_5026_50260801_148_dialog_content = "Agora!",
  ui_story_5026_50260801_149_dialog_content = "<size=45>Ah!</size>",
  ui_story_5026_50260801_150_dialog_content = "<color=#e8d9bb>Plop...</color>",
  ui_story_5026_50260801_151_dialog_content = "Sanae?",
  ui_story_5026_50260801_152_dialog_content = "Hã?!",
  ui_story_5026_50260901_1_dialog_content = "<anim type=Shake><size=45>A-Achoo!</size></anim>",
  ui_story_5026_50260901_2_dialog_content = "Toalha, Chubb!",
  ui_story_5026_50260901_3_dialog_content = "Esse Chubb é tão atencioso...",
  ui_story_5026_50260901_4_dialog_content = "É apenas um peixe. Como você pôde ser tão descuidado e cair na água?",
  ui_story_5026_50260901_5_dialog_content = "Você até deixou cair sua preciosa boneca... Manae provavelmente levou um susto.",
  ui_story_5026_50260901_6_dialog_content = "Finalmente encontrei algo em que sou bom. Eu só queria ganhar...",
  ui_story_5026_50260901_7_dialog_content = "Lamento tê-lo incomodado... Eu deveria ter me certificado de que estava de pé corretamente. Eu deveria ser o único a cuidar de você...",
  ui_story_5026_50260901_8_dialog_content = "E eu molhei suas saias...",
  ui_story_5026_50260901_9_dialog_content = "Sinto muito, Nina, Manae e Sr. Chubb...",
  ui_story_5026_50260901_10_dialog_content = "Um \"obrigado\" é tudo o que é necessário.",
  ui_story_5026_50260901_11_dialog_content = "Você ainda me considera uma jovem amante, mesmo que não estejamos mais na mansão?",
  ui_story_5026_50260901_12_dialog_content = "M-Mas eu sou sempre desajeitado e não posso fazer nada por você...",
  ui_story_5026_50260901_13_dialog_content = "O que você está falando? Se você não tivesse me dado cobertura, não teríamos como sair da mansão bem debaixo do nariz de Minos!",
  ui_story_5026_50260901_14_dialog_content = "É uma pena que eu não tenha visto sua expressão quando ele encontrou aquele buraco na cerca de rosas.",
  ui_story_5026_50260901_15_dialog_content = "Eu não sou muito inteligente... sempre lendo romances inúteis e sonhando acordado...",
  ui_story_5026_50260901_16_dialog_content = "O que isso tem a ver com você me tratando como uma pessoa normal?",
  ui_story_5026_50260901_17_dialog_content = "Na verdade, se não fossem todas as suas histórias sobre Cloud Island e os misteriosos Caelestites...",
  ui_story_5026_50260901_18_dialog_content = "Eu provavelmente não teria decidido deixar Umbraton e ver o mundo com meus próprios olhos.",
  ui_story_5026_50260901_19_dialog_content = "Eu ainda estaria sentado no meu quarto, de mau humor por causa da chuva ou algo assim.",
  ui_story_5026_50260901_20_dialog_content = "Então você não precisa pisar em ovos o tempo todo. Apenas diga o que está em sua mente.",
  ui_story_5026_50260901_21_dialog_content = "Nina...",
  ui_story_5026_50260901_22_dialog_content = "Não quero me intrometer, mas...",
  ui_story_5026_50260901_23_dialog_content = "De acordo com a necessidade de pessoal PlayerName falou comigo, tudo o que precisamos agora é de um madeireiro.",
  ui_story_5026_50260901_24_dialog_content = "Hmm...",
  ui_story_5026_50260901_25_dialog_content = "As roupas da senhorita Sanae ainda estão úmidas. Por que não fazemos uma pausa aqui?",
  ui_story_5026_50260901_26_dialog_content = "Usar Luminatics em um local quente e seco fará com que suas roupas sequem mais rápido.",
  ui_story_5026_50260901_27_dialog_content = "Sinto muito⁠ - quero dizer, obrigado, Lady Bethel.",
  ui_story_5026_50260901_28_dialog_content = "M-Mas... Eu queria perguntar... Que lugar é esse?",
  ui_story_5026_50260901_29_dialog_content = "PlayerName teve Chubb nos trazer aqui para descansar.",
  ui_story_5026_50260901_30_dialog_content = "É o mais próximo! E há toalhas aqui, Chubb!",
  ui_story_5026_50260901_31_dialog_content = "Mas este parece ser o quarto do Sr. Navegador...",
  ui_story_5026_50260901_32_dialog_content = "Ele tem sido gentil conosco. Eu deveria tentar arrumar este lugar para ele.",
  ui_story_5026_50260901_33_dialog_content = "V-Você quer dizer... Isso é...",
  ui_story_5026_50260901_34_dialog_content = "Eu nunca entrei no quarto de um menino!",
  ui_story_5026_50260901_35_dialog_content = "P-Por que você está cobrindo seus olhos, Nina?",
  ui_story_5026_50260901_36_dialog_content = "A realidade é bem diferente da ficção, não é?",
  ui_story_5026_50260901_37_dialog_content = "Senhora Betel?",
  ui_story_5026_50260901_38_dialog_content = "Na verdade, a pergunta mais importante é: por que você está tão à vontade, Sanae?",
  ui_story_5026_50260901_39_dialog_content = "Eu... servi muitas casas antes de vir para os Andersen.",
  ui_story_5026_50260901_40_dialog_content = "Então eu limpei os quartos de muitos meninos.",
  ui_story_5026_50260901_41_dialog_content = "Lembro-me de coisas como roupas sujas escondidas debaixo de camas feitas...",
  ui_story_5026_50260901_42_dialog_content = "Prateleiras cheias de figurinhas que eu não tinha permissão para tocar, mesmo que estivessem todas empoeiradas...",
  ui_story_5026_50260901_43_dialog_content = "Pilhas de coisas que cairiam sobre mim assim que abrisse o armário...",
  ui_story_5026_50260901_44_dialog_content = "Ah, e debaixo das camas—",
  ui_story_5026_50260901_45_dialog_content = "Uh... Nina... Você está bem?",
  ui_story_5026_50260901_46_dialog_content = "Isso é tão assustador... Este é o lugar mais aterrorizante que já estive nesta viagem até agora!",
  ui_story_5026_50260901_47_dialog_content = "É ainda mais assustador do que atravessar uma ponte suspensa!",
  ui_story_5026_50260901_48_dialog_content = "Você está bem, Srta. Nina.",
  ui_story_5026_50260901_49_dialog_content = "Ao enfrentar o desconhecido, o mais importante é obter todas as informações possíveis.",
  ui_story_5026_50260901_50_dialog_content = "Certa vez li um romance em que o protagonista masculino frio tinha um arsenal debaixo da cama.",
  ui_story_5026_50260901_51_dialog_content = "Quando os assassinos invadiram sua casa, ele pegou as armas e protegeu a liderança feminina!",
  ui_story_5026_50260901_52_dialog_content = "Ah... eu li esse livro também!",
  ui_story_5026_50260901_53_dialog_content = "Em outro romance, o protagonista masculino era um preguiçoso total, mas ele era leal ao protagonista feminino.",
  ui_story_5026_50260901_54_dialog_content = "No entanto, ele tinha pilhas de material classificado como R debaixo de sua cama.",
  ui_story_5026_50260901_55_dialog_content = "Então você gosta de romances! Você já leu⁠—",
  ui_story_5026_50260901_56_dialog_content = "Sanae... Vou sair.",
  ui_story_5026_50260901_57_dialog_content = "Nina? Espere por mim!",
  ui_story_5026_50260901_58_dialog_content = "É só cortar árvores. Eu posso fazer isso sozinho. Só venha mais tarde!",
  ui_story_5026_50260901_59_dialog_content = "A dona Nina está vermelha como um tomate. Acho que ela não está acostumada com esse tipo de assunto...",
  ui_story_5026_50260901_60_dialog_content = "Sanae, você acabou de dizer que leu \"The Umbraton Seductress\" também?",
  ui_story_5026_50260901_61_dialog_content = "Não é apenas o amor entre os protagonistas, a história de confiança e traição entre os membros da gangue também é tão atraente!",
  ui_story_5026_50260901_62_dialog_content = "Realmente retrata como é a vida de gangue em Umbraton. É um dos meus favoritos!",
  ui_story_5026_50260901_63_dialog_content = "Que tal \"The Returned Princess of Lumopolis\"?",
  ui_story_5026_50260901_64_dialog_content = "Ah esse, claro! Eu amo a cena do sequestro da noiva no casamento real!",
  ui_story_5026_50260901_65_dialog_content = "Fiquei tanto tempo na fila só para comprar a continuação...",
  ui_story_5026_50260901_66_dialog_content = "Ah! Hum... eu fiquei muito animado?",
  ui_story_5026_50260901_67_dialog_content = "Está bem! Finalmente encontrei alguém que gosta do que eu gosto. Tenho muito mais a dizer a você!",
  ui_story_5026_50260901_68_dialog_content = "Nina estava certa, sou muito falante quando encontro algo que gosto de falar.",
  ui_story_5026_50260901_69_dialog_content = "Mas eu sei... Não é só isso.",
  ui_story_5026_50260901_70_dialog_content = "Por muito tempo, pensei que Manae era a única que estava disposta a me ouvir falar.",
  ui_story_5026_50260901_71_dialog_content = "Nina me ensinou que havia pessoas no mundo que me aceitariam como eu era.",
  ui_story_5026_50260901_72_dialog_content = "Deve ser isso que me deu forças para conversar com você assim.",
  ui_story_5026_50260901_73_dialog_content = "Quero dizer, eu ainda te devo uma quantia enorme de dinheiro por quebrar o navio da Ilha das Nuvens...",
  ui_story_5026_50260901_74_dialog_content = "O velho eu nunca teria ousado falar com você...",
  ui_story_5026_50260901_75_dialog_content = "Dona Sana...",
  ui_story_5026_50260901_76_dialog_content = "Oh! Definitivamente vou trabalhar duro para ganhar de volta o dinheiro que lhe devo!",
  ui_story_5026_50260901_77_dialog_content = "Hehe, não há pressa. Mas chega de negócios...",
  ui_story_5026_50260901_78_dialog_content = "Vamos falar mais sobre \"The Returned Princess of Lumopolis II\"!",
  ui_story_5026_50260902_1_dialog_content = "<color=#e8d9bb>Jardins da Nuvem: Floresta</color>",
  ui_story_5026_50260902_2_dialog_content = "Não pensei que encontraria retardatários do Eclipsite ao longo do caminho. Custou mais tempo do que eu pensava.",
  ui_story_5026_50260902_3_dialog_content = "Obrigado por me mostrar o caminho.",
  ui_story_5026_50260902_4_dialog_content = "Chubb!",
  ui_story_5026_50260902_5_dialog_content = "Parece que eles preferem as sombras das árvores a campos abertos.",
  ui_story_5026_50260902_6_dialog_content = "A maioria dos animais tem medo de Eclipsitas. Você não é?",
  ui_story_5026_50260902_7_dialog_content = "Chubb?",
  ui_story_5026_50260902_8_dialog_content = "Que criatura estranha. Parece que não conhece o medo.",
  ui_story_5026_50260902_9_dialog_content = "Assim como aquele celestita.",
  ui_story_5026_50260902_10_dialog_content = "Não, talvez eu ache estranho só porque estou acostumado com Umbraton...",
  ui_story_5026_50260902_11_dialog_content = "Estou acostumado a estar cercado por pessoas que usam várias máscaras.",
  ui_story_5026_50260902_12_dialog_content = "Não se preocupe! Eu vou protegê-lo de qualquer Eclipsite!",
  ui_story_5026_50260902_13_dialog_content = "Nina! Por aqui!",
  ui_story_5026_50260902_14_dialog_content = "Como está Sanae? Ela estava completamente molhada quando saiu do rio.",
  ui_story_5026_50260902_15_dialog_content = "Ela está bem. Bethel está secando suas roupas com Luminatics agora.",
  ui_story_5026_50260902_16_dialog_content = "No seu quarto.",
  ui_story_5026_50260902_17_dialog_content = "No meu quarto!?",
  ui_story_5026_50260902_18_dialog_content = "Quarto com toalhas! O quarto mais próximo! Chubb!",
  ui_story_5026_50260902_19_dialog_content = "Tinha que ser meu quarto?",
  ui_story_5026_50260902_20_dialog_content = "PlayerName, debaixo da sua cama, você sabe, hum...",
  ui_story_5026_50260902_21_dialog_content = "Oh... Oh não, você os encontrou, não foi?",
  ui_story_5026_50260902_22_dialog_content = "O que...",
  ui_story_5026_50260902_23_dialog_content = "<size=45>H-Que sem vergonha!</size>",
  ui_story_5026_50260902_24_dialog_content = "Do que você está falando?",
  ui_story_5026_50260902_25_dialog_content = "É apenas um saco de sobras Crunchy Munchy Crunch e um Guia Pictórico da Natureza com páginas faltando!",
  ui_story_5026_50260902_26_dialog_content = "Eu tenho que admitir que o quarto está um pouco bagunçado... Eu estava planejando limpá-lo antes que Vice voltasse...",
  ui_story_5026_50260902_27_dialog_content = "O que... Então é...",
  ui_story_5026_50260902_28_option_content = "Do que você estava falando então?",
  ui_story_5026_50260902_29_dialog_content = "Nada mesmo!",
  ui_story_5026_50260902_30_option_content = "O que mais você esperava!?",
  ui_story_5026_50260902_31_dialog_content = "C-Como eu saberia!?",
  ui_story_5026_50260902_32_dialog_content = "Esqueça essas coisas bobas. Sobre o que você e Minos conversaram no rio?",
  ui_story_5026_50260902_33_dialog_content = "Bem... Só que você é a filha do Conde Andersen, e como você fugiu de casa.",
  ui_story_5026_50260902_34_dialog_content = "Eu sabia.",
  ui_story_5026_50260902_35_dialog_content = "Ele se ofereceu para pagar qualquer coisa que você quisesse para não me contratar?",
  ui_story_5026_50260902_36_dialog_content = "Gostaria de um cheque que liquidasse todas as minhas dívidas...",
  ui_story_5026_50260902_37_dialog_content = "Então você aceitou a oferta dele?",
  ui_story_5026_50260902_38_dialog_content = "Não! Claro que não! Eu só estava brincando.",
  ui_story_5026_50260902_39_dialog_content = "A propósito, não foi bom que tudo em sua loja estivesse esgotado?",
  ui_story_5026_50260902_40_dialog_content = "Quer dizer, as pessoas abrem uma loja para ganhar dinheiro, não é?",
  ui_story_5026_50260902_41_dialog_content = "Eu nem sei qual das suas palavras eu acho mais chocante...",
  ui_story_5026_50260902_42_dialog_content = "Bem... Eraveil raramente negociava com o mundo exterior, e Soroz não tinha muito a me ensinar sobre isso.",
  ui_story_5026_50260902_43_dialog_content = "Deixa para lá. Vou suportar sua ignorância, já que você é um importante parceiro de negócios.",
  ui_story_5026_50260902_44_dialog_content = "Para mim, não é apenas sobre o dinheiro.",
  ui_story_5026_50260902_45_dialog_content = "Você provavelmente pensa que eu sou uma princesa que não sabe como é a vida para a maioria.",
  ui_story_5026_50260902_46_dialog_content = "É claro que eu sei que tornar um negócio lucrativo não é pouca coisa.",
  ui_story_5026_50260902_47_dialog_content = "Mas o que eu quero é que meus designs ganhem a validação das pessoas.",
  ui_story_5026_50260902_48_dialog_content = "Meu pai estava preocupado que eu ficaria chateado se minhas coisas não vendessem, por isso ele comprou tudo.",
  ui_story_5026_50260902_49_dialog_content = "Mesmo que isso me chateasse, eu teria aceitado o resultado sabendo que tinha feito o meu melhor.",
  ui_story_5026_50260902_50_dialog_content = "Você sabia que Bethel se tornou a mão direita do Shadowlord quando ela não era muito mais velha que eu?",
  ui_story_5026_50260902_51_dialog_content = "Então seu objetivo é superar Bethel e ser o maior mercador de Umbraton?",
  ui_story_5026_50260902_52_dialog_content = "Tch... amadores podem ser tão simplórios.",
  ui_story_5026_50260902_53_dialog_content = "Deixa para lá. Não me surpreende que você pense assim.",
  ui_story_5026_50260902_54_dialog_content = "Claro, as pessoas muitas vezes me comparam a ela nos muitos eventos sociais de Umbraton.",
  ui_story_5026_50260902_55_dialog_content = "Ela é incrível à sua maneira, mas abri minhas lojas porque queria seguir minhas paixões.",
  ui_story_5026_50260902_56_dialog_content = "Mas não se engane, seja lá o que ela for capaz, eu também serei capaz, um dia!",
  ui_story_5026_50260902_57_dialog_content = "O-Por conta própria, claro, sem depender do meu pai ou de qualquer outra pessoa!",
  ui_story_5026_50260902_58_dialog_content = "(Mesmo que ela não admita, ela ainda está se comparando a Betel.)",
  ui_story_5026_50260902_59_dialog_content = "Não confiar em ninguém... hmm.",
  ui_story_5026_50260902_60_dialog_content = "Nina.",
  ui_story_5026_50260902_61_dialog_content = "Huh? O que há com a seriedade repentina?",
  ui_story_5026_50260902_62_dialog_content = "Eu nunca conheci meus pais, exceto em meus sonhos.",
  ui_story_5026_50260902_63_dialog_content = "Como o último celestita que saiu deste continente, eu estava sempre sozinho.",
  ui_story_5026_50260902_64_dialog_content = "Eu costumava pensar que esperaria o fim com Soroz underground.",
  ui_story_5026_50260902_65_dialog_content = "Mas então, um dia, Vice caiu do céu e me trouxe para um mundo totalmente novo.",
  ui_story_5026_50260902_66_dialog_content = "Fiz muitos amigos ao longo de nossa jornada e vivenciei aventuras incríveis.",
  ui_story_5026_50260902_67_dialog_content = "Quando eu estava desamparado e sozinho, eles me deram muito apoio.",
  ui_story_5026_50260902_68_dialog_content = "Sem eles, eu não estaria aqui agora.",
  ui_story_5026_50260902_69_dialog_content = "Você nunca lutou com eles antes?",
  ui_story_5026_50260902_70_dialog_content = "Claro que sim, mas no final, sempre chegamos a um entendimento.",
  ui_story_5026_50260902_71_dialog_content = "Estaríamos próximos se não gostássemos do que o outro estava fazendo.",
  ui_story_5026_50260902_72_dialog_content = "Comunique-se com as pessoas de quem você gosta enquanto elas ainda estão por perto. Não diga coisas que você vai se arrepender mais tarde.",
  ui_story_5026_50260902_73_dialog_content = "Você não planeja nunca mais voltar para casa, só porque está bravo com seu pai, não é?",
  ui_story_5026_50260902_74_dialog_content = "O-Claro que não...",
  ui_story_5026_50260902_75_dialog_content = "Se você pudesse dizer a ele o que você acabou de me dizer hoje...",
  ui_story_5026_50260902_76_dialog_content = "Tenho certeza de que ele entenderia e nunca mais cometeria o mesmo erro.",
  ui_story_5026_50260902_77_dialog_content = "(Ele é um homem que fecha o mundo só porque sua filha está brava com ele...)",
  ui_story_5026_50260902_78_dialog_content = "Você tentou falar com seu pai antes de fugir de casa?",
  ui_story_5026_50260902_79_dialog_content = "...",
  ui_story_5026_50260902_80_dialog_content = "Fale com ele? ... Eu entendo.",
  ui_story_5026_50260902_81_dialog_content = "Mas antes disso, quero alcançar o que me propus a alcançar.",
  ui_story_5026_50260902_82_dialog_content = "Essa é a única maneira de provar a ele que não preciso contar com ele para conseguir as coisas!",
  ui_story_5026_50260902_83_dialog_content = "Patrulhamos todos os Cloud Gardens, certo?",
  ui_story_5026_50260902_84_dialog_content = "Sim, exterminamos todos os Eclipsites que encontramos.",
  ui_story_5026_50260902_85_dialog_content = "Agora que isso está feito, as operações de negócios são as próximas da lista.",
  ui_story_5026_50260902_86_dialog_content = "Pensei em transformar este lugar em um resort idílico e ganhar meu maço de dinheiro com as taxas de admissão e acomodação.",
  ui_story_5026_50260902_87_dialog_content = "Taxas de hospedagem? Todos aqui são meus amigos, eu nunca...",
  ui_story_5026_50260902_88_dialog_content = "Desenvolvendo então o terreno circundante, tornando-o o coração de uma grande rede logística que abrange todo o continente.",
  ui_story_5026_50260902_89_dialog_content = "O que é uma... rede logística?",
  ui_story_5026_50260902_90_dialog_content = "E então usar o fascinante Colossus, que é muito mais avançado do que qualquer tecnologia auroriana, para transportar mercadorias.",
  ui_story_5026_50260902_91_dialog_content = "Não deve ser difícil para alguém tão famoso quanto você receber pedidos, certo, PlayerName?",
  ui_story_5026_50260902_92_dialog_content = "Eu não acho que eles teriam muito negócio a ver comigo...",
  ui_story_5026_50260902_93_dialog_content = "Há negócios em todos os lugares com todos, PlayerName. É, em última análise, sobre o que está sendo vendido.",
  ui_story_5026_50260902_94_dialog_content = "Mesmo os grandes clientes autossuficientes que não fazem negócios com as guildas Umbraton...",
  ui_story_5026_50260902_95_dialog_content = "Não hesitaria em tentar construir um relacionamento com o Último Celestita.",
  ui_story_5026_50260902_96_dialog_content = "Não seria exagero pensar que toda a economia do Astra poderia um dia estar ao nosso alcance...",
  ui_story_5026_50260902_97_dialog_content = "Isso é realmente muito rebuscado...",
  ui_story_5026_50260902_98_dialog_content = "Mas esse é o plano de dominação mundial que fiz para você.",
  ui_story_5026_50260902_99_dialog_content = "\"Agora, então, devemos começar.\"",
  ui_story_5026_50260902_100_dialog_content = "Isso é o que eu queria dizer, mas posso ver que você tem outra coisa em mente.",
  ui_story_5026_50260902_101_dialog_content = "Assim como você disse, é importante se comunicar.",
  ui_story_5026_50260902_102_dialog_content = "Especialmente se formos parceiros de negócios interdependentes. Então vá em frente, diga sua parte.",
  ui_story_5026_50260902_103_dialog_content = "O que eu acho...",
  ui_story_5026_50260902_104_dialog_content = "(Que tipo de lugar eu quero que Cloud Gardens fique depois de remover todos os Eclipsites?)",
  ui_story_5026_50260902_105_dialog_content = "(Depois de vasculhar cada centímetro deste lugar com meus próprios olhos...)",
  ui_story_5026_50260902_106_dialog_content = "Eu...",
  ui_story_5026_50260902_107_dialog_content = "Desculpe interromper, Srta. Nina, Sr. Navegador.",
  ui_story_5026_50260902_108_dialog_content = "Mas há algo que eu preciso relatar para PlayerName.",
  ui_story_5026_50260902_109_dialog_content = "Não havia sinais de Eclipsitas enquanto coletávamos madeira, mas agora...",
  ui_story_5026_50260902_110_dialog_content = "Um grupo deles está se aproximando da floresta à frente.",
  ui_story_5026_50261001_1_dialog_content = "Ufa... Essa deve ser a última.",
  ui_story_5026_50261001_2_dialog_content = "PlayerName?",
  ui_story_5026_50261001_3_dialog_content = "O que está acontecendo...?",
  ui_story_5026_50261001_4_dialog_content = "Eu posso sentir Darkflow cercando Cloud Gardens...",
  ui_story_5026_50261001_5_dialog_content = "Minha habilidade deu errado?",
  ui_story_5026_50261001_6_dialog_content = "Algo ruim está acontecendo!",
  ui_story_5026_50261001_7_dialog_content = "O que houve?",
  ui_story_5026_50261001_8_dialog_content = "Depois que saímos do dormitório para te encontrar, vimos...",
  ui_story_5026_50261001_9_dialog_content = "Você tem que ver com seus próprios olhos para acreditar. Venha, eu vou te mostrar!",
  ui_story_5026_50261001_10_dialog_content = "O que está acontecendo... Acabamos de limpar este lugar de todos os Eclipsitas, não foi?",
  ui_story_5026_50261001_11_dialog_content = "Primeiro pensei que os Eclipsites encontrados aqui fossem apenas alguns retardatários...",
  ui_story_5026_50261001_12_dialog_content = "Então, em minha patrulha por Cloud Gardens, percebi que provavelmente não era tão simples assim.",
  ui_story_5026_50261001_13_dialog_content = "E agora...",
  ui_story_5026_50261001_14_dialog_content = "Eu realmente sou muito ingênuo.",
  ui_story_5026_50261001_15_dialog_content = "W-Nós só precisamos expulsá-los, certo?",
  ui_story_5026_50261001_16_dialog_content = "Já me sinto mal por não te pagar durante a sua liberdade condicional...",
  ui_story_5026_50261001_17_dialog_content = "Mas esta crise superou em muito as minhas expectativas.",
  ui_story_5026_50261001_18_dialog_content = "Umbraton definitivamente contrataria mercenários permanentes se uma de suas cidades encontrasse tantos Eclipsitas.",
  ui_story_5026_50261001_19_dialog_content = "Isso, sem dúvida, geraria custos extras, no entanto.",
  ui_story_5026_50261001_20_dialog_content = "Eu não quero estar acumulando dívidas quando Cloud Gardens está apenas começando o desenvolvimento, mas parece que não tenho escolha...",
  ui_story_5026_50261001_21_dialog_content = "Vou voltar para Umbraton e entrar em contato com mercenários registrados no Quartel-General da Guilda.",
  ui_story_5026_50261001_22_dialog_content = "Vai ser mais rápido voar no Colossus, mas você provavelmente não quer deixar Cloud Gardens assim, certo, PlayerName?",
  ui_story_5026_50261001_23_dialog_content = "Eu sei que você tem um orçamento limitado, então farei o meu melhor para obter descontos!",
  ui_story_5026_50261001_24_dialog_content = "O que devemos fazer agora, PlayerName?",
  ui_story_5026_50261001_25_dialog_content = "Parece que os Eclipsites ainda não nos descobriram.",
  ui_story_5026_50261001_26_dialog_content = "Hmm... Eles não parecem estar se movendo com nenhum propósito.",
  ui_story_5026_50261001_27_dialog_content = "Pelo menos, isso significa que não é um ataque ordenado por um Eclipsite de alto nível.",
  ui_story_5026_50261001_28_dialog_content = "Provavelmente não teremos tanta sorte da próxima vez se não encontrarmos uma solução sustentável a longo prazo.",
  ui_story_5026_50261001_29_dialog_content = "Senti menos atividades do Eclipsite ao redor da Hyacinth Tower. Vamos esperar lá o Betel voltar.",
  ui_story_5026_50261201_1_dialog_content = "(O Obelisco do Retorno definitivamente expulsou todos os Eclipsites presentes em Eraveil na época...)",
  ui_story_5026_50261201_2_dialog_content = "(Então esses Eclipsitas devem ter vindo de outros lugares.)",
  ui_story_5026_50261201_3_dialog_content = "(Nina estava certa... A paz é rara e preciosa...)",
  ui_story_5026_50261201_4_dialog_content = "(Eu nem quero saber o quão caro pode ser a contratação de mercenários da Umbraton a longo prazo!)",
  ui_story_5026_50261201_5_dialog_content = "Aí está você, PlayerName.",
  ui_story_5026_50261201_6_dialog_content = "...",
  ui_story_5026_50261201_7_dialog_content = "Ei, PlayerName!",
  ui_story_5026_50261201_8_dialog_content = "Nina...?",
  ui_story_5026_50261201_9_dialog_content = "E-eu não vim porque eu estava preocupado ou qualquer coisa!",
  ui_story_5026_50261201_10_dialog_content = "É que não posso deixar que seu humor desanimado afete os negócios!",
  ui_story_5026_50261201_11_dialog_content = "Isso é tudo!",
  ui_story_5026_50261201_12_dialog_content = "Então você está aqui porque você se importa.",
  ui_story_5026_50261201_13_dialog_content = "Ugh... se você deve colocar dessa forma, suponho que não seja totalmente impreciso.",
  ui_story_5026_50261201_14_dialog_content = "Minos e Sanae estão vigiando. Nenhum eclipse chegará perto.",
  ui_story_5026_50261201_15_dialog_content = "De qualquer forma, vamos nos sentar ali.",
  ui_story_5026_50261201_16_dialog_content = "Por que você parece ter mais coisas em mente do que eu?",
  ui_story_5026_50261201_17_dialog_content = "Minos vai me levar de volta para Umbraton em breve.",
  ui_story_5026_50261201_18_dialog_content = "Fiz uma aposta com ele. Se eu o vencesse em apenas uma coisa, ele me deixaria em paz.",
  ui_story_5026_50261201_19_dialog_content = "Você não teve chance.",
  ui_story_5026_50261201_20_dialog_content = "S-Cala a boca!",
  ui_story_5026_50261201_21_dialog_content = "Eu... deveria saber que Minos não teria concordado se não estivesse confiante de que venceria.",
  ui_story_5026_50261201_22_dialog_content = "Seja plantando as Árvores Únicas, cavando tesouros ou pescando...",
  ui_story_5026_50261201_23_dialog_content = "Eu perdi esse último também, não foi?",
  ui_story_5026_50261201_24_dialog_content = "Se fizermos comparações...",
  ui_story_5026_50261201_25_dialog_content = "Minos categorizou a madeira que ele coletou e até anotou o melhor uso para cada tipo.",
  ui_story_5026_50261201_26_dialog_content = "Aparentemente, ele também usou um método chamado \"registro seletivo\" para garantir que as árvores restantes crescessem melhor.",
  ui_story_5026_50261201_27_dialog_content = "Eu sempre corto a árvore que fica mais perto de mim... Eu nem sabia que existia esse método.",
  ui_story_5026_50261201_28_dialog_content = "Então isso significa que não importa quanta madeira Sanae e eu coletávamos... Estávamos destinados a perder desde o início.",
  ui_story_5026_50261201_29_dialog_content = "Bem... Como nosso mordomo, essa habilidade é de se esperar.",
  ui_story_5026_50261201_30_dialog_content = "Você está elogiando ele?",
  ui_story_5026_50261201_31_dialog_content = "Estou apenas reconhecendo meus fracassos e falando a verdade.",
  ui_story_5026_50261201_32_dialog_content = "Mas como você já deve saber, o objetivo dele é apenas me levar para casa.",
  ui_story_5026_50261201_33_dialog_content = "No final, você ainda não tem ninguém adequado para gerenciar Cloud Gardens.",
  ui_story_5026_50261201_34_dialog_content = "Você não precisa se preocupar com isso.",
  ui_story_5026_50261201_35_dialog_content = "Pode parecer inacreditável, mas Minos disse...",
  ui_story_5026_50261201_36_dialog_content = "Enquanto passava pelas tarefas diárias, ele conseguiu ensinar aos Chubb Farmers como trabalhar como ele.",
  ui_story_5026_50261201_37_dialog_content = "Então é por isso que eles o chamavam de \"Mestre\".",
  ui_story_5026_50261201_38_dialog_content = "Ele diz que, apesar de limitados por sua natureza, ainda são bons aprendizes.",
  ui_story_5026_50261201_39_dialog_content = "No mínimo, sob seus cuidados, não deve haver nenhuma Árvore Única que não cresça.",
  ui_story_5026_50261201_40_dialog_content = "Contratar um mordomo como Minos provavelmente está fora do meu orçamento de qualquer maneira...",
  ui_story_5026_50261201_41_dialog_content = "Eu nem sabia que ele conseguia fazer isso... Tch, como se me derrotar não fosse suficiente.",
  ui_story_5026_50261201_42_dialog_content = "Mas... eu estava pensando que talvez fosse realmente um pouco imprudente simplesmente fugir de casa assim.",
  ui_story_5026_50261201_43_dialog_content = "V-você não foi quem colocou a ideia na minha cabeça!",
  ui_story_5026_50261201_44_dialog_content = "Ainda estou com raiva de meu pai pelo que ele fez, e de Minos por ficar do lado de papai o tempo todo.",
  ui_story_5026_50261201_45_dialog_content = "Mas estou mais chateado comigo mesmo.",
  ui_story_5026_50261201_46_dialog_content = "Que arrogante da minha parte estipular um grande plano de negócios para você quando nem consigo lidar com o problema do Eclipse.",
  ui_story_5026_50261201_47_dialog_content = "E estraguei totalmente o trabalho de plantar árvores... Estou longe de ser a pessoa que disse que seria.",
  ui_story_5026_50261201_48_dialog_content = "Você não estragou nada... embora não tenha sido ótimo...",
  ui_story_5026_50261201_49_dialog_content = "Hum? O que você quer chegar?",
  ui_story_5026_50261201_50_dialog_content = "Nada! Eu acho que seu grande plano de negócios é legal! É bastante criativo e imaginativo!",
  ui_story_5026_50261201_51_dialog_content = "Heh... Não poderia haver pior crítica para um plano de negócios.",
  ui_story_5026_50261201_52_dialog_content = "Admito que há muitas coisas que preciso resolver, como questões geográficas e de transporte, sem falar...",
  ui_story_5026_50261201_53_dialog_content = "Um grande centro de negócios precisa de cafés, restaurantes e parques de diversões, assim como a Umbraton!",
  ui_story_5026_50261201_54_dialog_content = "Hmm... Como devo colocar?",
  ui_story_5026_50261201_55_dialog_content = "Eu realmente não vejo Cloud Gardens se tornando um hub central para negócios...",
  ui_story_5026_50261201_56_dialog_content = "Tampouco posso imaginar Soroz sendo uma ferramenta de negócios.",
  ui_story_5026_50261201_57_dialog_content = "Soroz tem uma mente própria.",
  ui_story_5026_50261201_58_dialog_content = "Pelo menos... uma vez foi. Ele me levantou.",
  ui_story_5026_50261201_59_dialog_content = "Durante muito tempo, ensinou-me tudo o que sei sobre os celestitas.",
  ui_story_5026_50261201_60_dialog_content = "(O que diria se me visse agora...?)",
  ui_story_5026_50261201_61_dialog_content = "Eu vejo. Peço desculpas por não ser atencioso o suficiente.",
  ui_story_5026_50261201_62_dialog_content = "Então, me diga o que você tem em mente.",
  ui_story_5026_50261201_63_dialog_content = "O quê?",
  ui_story_5026_50261201_64_dialog_content = "O que você quer que o Cloud Gardens se torne?",
  ui_story_5026_50261201_65_dialog_content = "...",
  ui_story_5026_50261201_66_dialog_content = "Em Eraveil, um celestita uma vez desertou para os Eclipsitas para ganhar poder ao custo de toda a minha raça.",
  ui_story_5026_50261201_67_dialog_content = "O método que ela usou para buscar o poder estava completamente errado, não há como negar isso.",
  ui_story_5026_50261201_68_dialog_content = "Mas andei pensando...",
  ui_story_5026_50261201_69_dialog_content = "Havia outras coisas que a levaram por esse caminho além de arrogância e covardia?",
  ui_story_5026_50261201_70_dialog_content = "Ainda não sei a história completa. Tudo o que sei são pedaços e pedaços.",
  ui_story_5026_50261201_71_dialog_content = "Só sei que, mesmo no final, ela não conseguiu a paz e a tranquilidade que queria.",
  ui_story_5026_50261201_72_dialog_content = "Então... eu quero fazer deste lugar um refúgio pacífico e sereno para todos.",
  ui_story_5026_50261201_73_dialog_content = "Um lugar diferente do Eraveil que pertencia aos meus ancestrais.",
  ui_story_5026_50261201_74_dialog_content = "PlayerName...",
  ui_story_5026_50261201_75_dialog_content = "Você colocou bem. Até eu estou um pouco... não, estou muito emocionado com suas palavras.",
  ui_story_5026_50261201_76_dialog_content = "Mas, preciso de detalhes. O que você pretende construir aqui?",
  ui_story_5026_50261201_77_dialog_content = "Você é tão pragmático... Acho que tive uma conversa parecida com Bethel antes.",
  ui_story_5026_50261201_78_dialog_content = "Chama-se ser prático. É melhor você se acostumar com a forma como fazemos as coisas em Umbraton.",
  ui_story_5026_50261201_79_dialog_content = "De acordo com o que Bethel escreveu no anúncio de recrutamento, obter lucro é uma obrigação, não é?",
  ui_story_5026_50261201_80_dialog_content = "Sim... Quem diria que as informações de Sheol seriam tão caras...",
  ui_story_5026_50261201_81_dialog_content = "Subestimar o valor de uma informação... Que noob.",
  ui_story_5026_50261201_82_dialog_content = "Existe alguma maneira de ganhar muito Nightium de uma só vez, como ganhar na loteria?",
  ui_story_5026_50261201_83_dialog_content = "PlayerName, você sabe alguma coisa sobre empresas cinzentas?",
  ui_story_5026_50261201_84_dialog_content = "Parece esboçado...",
  ui_story_5026_50261201_85_dialog_content = "Lucro maciço de curto prazo de fontes desconhecidas. Muitas guildas em Umbraton têm esses recursos...",
  ui_story_5026_50261201_86_dialog_content = "Incluindo os Andersen, antes de meu pai assumir.",
  ui_story_5026_50261201_87_dialog_content = "Acabei de ouvir algo que não deveria ter ouvido?",
  ui_story_5026_50261201_88_dialog_content = "Eu não estou pedindo para você fazer o mesmo, eu estava apenas trazendo isso como uma opção.",
  ui_story_5026_50261201_89_dialog_content = "Como alguém pode ficar à vontade para ganhar dinheiro sem saber de onde vem, especialmente considerando que alguém poderia ter sido prejudicado no processo?",
  ui_story_5026_50261201_90_dialog_content = "Os outros não sei, mas para meu pai, eles vieram como herança.",
  ui_story_5026_50261201_91_dialog_content = "Mesmo que ele tenha tirado nossa família de negócios tão obscuros, ele não podia fazer nada sobre um legado passado sobre o qual não tinha controle.",
  ui_story_5026_50261201_92_dialog_content = "No entanto, ele foi capaz de decidir como utilizar essa herança.",
  ui_story_5026_50261201_93_dialog_content = "Uma vez, ele me disse algo depois que visitamos as clínicas e orfanatos financiados pelos Andersen.",
  ui_story_5026_50261201_94_dialog_content = "\"O passado está no passado. Hoje e amanhã, no entanto, ainda estão em nossas mãos.\"",
  ui_story_5026_50261201_95_dialog_content = "Alguns em Umbraton consideram a caridade dos ricos, a arrogância de um nobre decadente ou até o veneno de uma víbora disfarçado...",
  ui_story_5026_50261201_96_dialog_content = "Hmph! Talvez eles pensem que podem ascender a Lumopolis em sua escada de marfim da moralidade!",
  ui_story_5026_50261201_97_dialog_content = "Mas eu vi com meus próprios olhos quantos se beneficiaram da herança.",
  ui_story_5026_50261201_98_dialog_content = "Eu me pergunto se o pai tem cuidado de si mesmo enquanto eu estive fora...",
  ui_story_5026_50261201_99_dialog_content = "Se ele estivesse aqui, ele poderia lhe dar melhores conselhos, PlayerName.",
  ui_story_5026_50261201_100_dialog_content = "Eu discordo... Enfim...",
  ui_story_5026_50261201_101_dialog_content = "Nina, você realmente ama muito seu pai, não é?",
  ui_story_5026_50261201_102_dialog_content = "O que te deu essa ideia!? Multar. A culpa é minha por desviar do assunto primeiro...",
  ui_story_5026_50261201_103_dialog_content = "Eu realmente não chamaria isso de digressão.",
  ui_story_5026_50261201_104_dialog_content = "Cloud Gardens e os Chubbs são... minha herança, por assim dizer.",
  ui_story_5026_50261201_105_dialog_content = "Mas por uma miríade de razões, não consegui prestar muita atenção até agora.",
  ui_story_5026_50261201_106_dialog_content = "Talvez haja algum ganho inesperado com tudo isso...",
  ui_story_5026_50261201_107_dialog_content = "<size=45>Concordo!</size>",
  ui_story_5026_50261201_108_dialog_content = "Uh o quê?",
  ui_story_5026_50261201_109_dialog_content = "Você não presta atenção suficiente aos Chubbs!",
  ui_story_5026_50261201_110_dialog_content = "Mesmo que eu esteja mais acostumado a notar detalhes nas aparências físicas, ser designer e tudo mais...",
  ui_story_5026_50261201_111_dialog_content = "Como você pode não dizer a diferença entre os Chubbs?",
  ui_story_5026_50261201_112_dialog_content = "Mesmo que você não possa dizer apenas olhando para eles, de acordo com Sanae eles também têm personalidades diferentes.",
  ui_story_5026_50261201_113_dialog_content = "Personalidades diferentes? Sério?",
  ui_story_5026_50261201_114_dialog_content = "Sanae sentiu pena de pensar que eram iguais, então prestou mais atenção neles.",
  ui_story_5026_50261201_115_dialog_content = "Mas você não precisa ser tão observador quanto ela para contar. Quero dizer, você já deve saber disso depois de passar tanto tempo com eles.",
  ui_story_5026_50261201_116_dialog_content = "PlayerName, você já pensou em treinar seus funcionários periodicamente?",
  ui_story_5026_50261201_117_dialog_content = "Ou trabalhando com eles para resolver problemas que você encontra ao gerenciar o negócio?",
  ui_story_5026_50261201_118_dialog_content = "Embora... não há o que falar se não nos livrarmos dos Eclipsitas primeiro...",
  ui_story_5026_50261201_119_dialog_content = "Você se torna tão aterrorizante assim que começa a falar sobre assuntos de negócios...",
  ui_story_5026_50261201_120_dialog_content = "<size=45>S-Cala a boca!</size> Estou tentando te ajudar!",
  ui_story_5026_50261201_121_dialog_content = "Eu sei, e estou agradecido, Nina.",
  ui_story_5026_50261201_122_dialog_content = "Graças ao que você disse antes, eu realmente pensei em algo. Claro, eu preciso experimentá-lo primeiro.",
  ui_story_5026_50261201_123_dialog_content = "Vou tentar atuar como o Mestre dos Jardins das Nuvens...",
  ui_story_5026_50261201_124_dialog_content = "Um método celestita.",
  ui_story_5026_50261301_1_dialog_content = "O que você está procurando nos arbustos? Acho que não tem nada aí.",
  ui_story_5026_50261301_2_dialog_content = "Que tipo de método celestita é esse?",
  ui_story_5026_50261301_3_dialog_content = "Eu sabia. Essas ruínas são exatamente as mesmas dos prédios que restaurei usando as plantas.",
  ui_story_5026_50261301_4_dialog_content = "Dormitórios, poços... Pelo que parece, Cloud Gardens definitivamente costumava ser uma grande área residencial.",
  ui_story_5026_50261301_5_dialog_content = "Mas, há muito poucos sinais de quaisquer postos de sentinela.",
  ui_story_5026_50261301_6_dialog_content = "Já que as medidas defensivas no Obelisco do Retorno são realmente difíceis de ativar...",
  ui_story_5026_50261301_7_dialog_content = "É provável que Cloud Gardens tenha seu próprio conjunto de medidas defensivas automatizadas.",
  ui_story_5026_50261301_8_dialog_content = "Nada mal, PlayerName!",
  ui_story_5026_50261301_9_option_content = "Impressionado?",
  ui_story_5026_50261301_10_dialog_content = "J-Só um pouco.",
  ui_story_5026_50261301_11_option_content = "Ele Ele.",
  ui_story_5026_50261301_12_dialog_content = "Não seja muito cheio de si.",
  ui_story_5026_50261301_13_dialog_content = "Eu não pensei que estudar essas plantas seria tão útil.",
  ui_story_5026_50261301_14_dialog_content = "Isso me lembra... Talvez saiba das medidas defensivas.",
  ui_story_5026_50261301_15_dialog_content = "<anim type=Shake>Bufê, bufo...</anim>",
  ui_story_5026_50261301_16_dialog_content = "Acordar! Acordar!",
  ui_story_5026_50261301_17_dialog_content = "Um Chubb com um bigode comprido... parece fofo.",
  ui_story_5026_50261301_18_dialog_content = "Ah, é o Mestre! Encontrou novas plantas, Chubb?",
  ui_story_5026_50261301_19_dialog_content = "Não estou aqui por causa dos projetos de hoje.",
  ui_story_5026_50261301_20_dialog_content = "Quero saber se há algum sistema de defesa aqui em Cloud Gardens.",
  ui_story_5026_50261301_21_dialog_content = "Claro. Chubb.",
  ui_story_5026_50261301_22_dialog_content = "Sério?! Por que você não me contou antes?",
  ui_story_5026_50261301_23_dialog_content = "O Mestre não perguntou antes, Chubb.",
  ui_story_5026_50261301_24_dialog_content = "Algo tão importante deveria ter sido informado a mim antes de me ensinar a plantar árvores!",
  ui_story_5026_50261301_25_dialog_content = "Não entendo. Vem de novo, Chubb?",
  ui_story_5026_50261301_26_dialog_content = "(De repente estou me lembrando de como foi frustrante tentar falar com Neural Aux no Obelisco do Retorno...)",
  ui_story_5026_50261301_27_dialog_content = "Como faço para ativar este sistema de defesa?",
  ui_story_5026_50261301_28_dialog_content = "Você pode ativar ou desativar o sistema de defesa direcionado a partir do terminal de controle na Hyacinth Tower, Chubb.",
  ui_story_5026_50261301_29_dialog_content = "Como chego ao terminal de controle?",
  ui_story_5026_50261301_30_dialog_content = "Informações confidenciais acessadas. Mudando o modo de interação. Verificando acesso...",
  ui_story_5026_50261301_31_dialog_content = "Alvo: PlayerName, o Último Celestita.",
  ui_story_5026_50261301_32_dialog_content = "Verificando o código de classe \"Defender\"... Falha na verificação.",
  ui_story_5026_50261301_33_dialog_content = "Encerrando o processo de verificação...",
  ui_story_5026_50261301_34_dialog_content = "Decreto mais alto verificado.",
  ui_story_5026_50261301_35_dialog_content = "PlayerNameOs comandos de devem ser seguidos, PlayerNameos desejos de se concretizaram.",
  ui_story_5026_50261301_36_dialog_content = "Acesso verificado. Informações confidenciais desbloqueadas.",
  ui_story_5026_50261301_37_dialog_content = "PlayerName o celestita.",
  ui_story_5026_50261301_38_dialog_content = "Sim! Estou aqui!",
  ui_story_5026_50261301_39_dialog_content = "De repente parece que estamos falando com um ancião...",
  ui_story_5026_50261301_40_dialog_content = "Para virar a bancada e acessar o terminal de controle, você precisa se conectar com quatro ou mais Chubbs e sintetizar a Chave Secreta.",
  ui_story_5026_50261301_41_dialog_content = "Informações confidenciais transmitidas. Mudando o modo de interação.",
  ui_story_5026_50261301_42_dialog_content = "A- Mais alguma coisa?",
  ui_story_5026_50261301_43_dialog_content = "<anim type=Shake>Ronco...</anim>",
  ui_story_5026_50261301_44_dialog_content = "<size=45>Cochilou!</size>",
  ui_story_5026_50261301_45_dialog_content = "A bancada deve ser a coisa que eu uso para fazer móveis... Então o terminal de controle fica embaixo dela?",
  ui_story_5026_50261301_46_dialog_content = "Eu bati com força na última vez quando estava fazendo uma mesa... Espero não ter danificado.",
  ui_story_5026_50261301_47_dialog_content = "Em vez de se preocupar com isso, por que você não vai e encontra mais três Chubbs primeiro?",
  ui_story_5026_50261301_48_dialog_content = "Certo. Provavelmente haverá algumas batalhas ao longo do caminho.",
  ui_story_5026_50261301_49_dialog_content = "Acho que vou ter que te ajudar mais uma vez. Não importa quais eclipses encontrarmos, eu vou...",
  ui_story_5026_50261301_50_dialog_content = "Quero dizer, Sanae e eu e todos, devemos protegê-lo!",
  ui_story_5026_50261301_51_dialog_content = "Apenas faça jus ao seu papel como comandante. Não me atrase!",
  ui_story_5026_50261402_1_dialog_content = "Ah! Aqui funciona né?",
  ui_story_5026_50261402_2_dialog_content = "Agora temos todos os Chubbs que precisamos.",
  ui_story_5026_50261402_3_dialog_content = "Mas eu quero ser segurado um pouco mais, Chubb.",
  ui_story_5026_50261402_4_dialog_content = "Hmm... Então, que tal eu—",
  ui_story_5026_50261402_5_dialog_content = "Sanae, apenas ignore.",
  ui_story_5026_50261402_6_dialog_content = "(Estou começando a entender o que Sanae quis dizer com eles terem personalidades diferentes...)",
  ui_story_5026_50261402_7_dialog_content = "(E apenas entre esses quatro Chubbs, posso realmente diferenciá-los pela aparência.)",
  ui_story_5026_50261402_8_dialog_content = "Então o que eu preciso fazer é me conectar com eles para sintetizar a Chave Secreta? É isso?",
  ui_story_5026_50261402_9_dialog_content = "Se desejar, você pode começar a se conectar ao Chubbs em ordem.",
  ui_story_5026_50261402_10_dialog_content = "Em ordem?",
  ui_story_5026_50261402_11_dialog_content = "Chubb Scholar é o terceiro, Chubb.",
  ui_story_5026_50261402_12_dialog_content = "E Elder Chubb é o segundo, Chubb.",
  ui_story_5026_50261402_13_dialog_content = "Está bem então...",
  ui_story_5026_50261402_14_dialog_content = "Chubb Merchant deve ser o terceiro, Chubb.",
  ui_story_5026_50261402_15_dialog_content = "Calma, quê?",
  ui_story_5026_50261402_16_dialog_content = "Chubb Merchant acha que Chubb Scholar é o primeiro, Chubb.",
  ui_story_5026_50261402_17_dialog_content = "Chubb Farmer é o primeiro, Chubb.",
  ui_story_5026_50261402_18_dialog_content = "Chubb Farmer lembra que o Elder Chubb deveria ser o quarto, Chubb.",
  ui_story_5026_50261402_19_dialog_content = "Até você está agindo como se soubesse...",
  ui_story_5026_50261402_20_dialog_content = "Vocês não podem me dizer a seqüência? Elder Chubb deve saber com certeza, certo?",
  ui_story_5026_50261402_21_dialog_content = "Estou velho e não me lembro, Chubb.",
  ui_story_5026_50261402_22_dialog_content = "<size=45>Sua memória estava perfeitamente bem apenas um momento atrás!</size>",
  ui_story_5026_50261402_23_dialog_content = "Mas eu sei que suas palavras estão meio certas e meio erradas, Chubb.",
  ui_story_5026_50261402_24_dialog_content = "Então... eu não consigo me conectar a menos que eu receba o pedido certo?",
  ui_story_5026_50261402_25_dialog_content = "Claro que você pode, mas então você vai abrir mão do prazer de ter resolvido um quebra-cabeça, Chubb.",
  ui_story_5026_50261402_26_dialog_content = "O Mestre deve saber como resolvê-lo. Chubb?",
  ui_story_5026_50261402_27_option_content = "Claro que eu faço!",
  ui_story_5026_50261402_28_dialog_content = "A ordem é: agricultor, ancião, comerciante, erudito.",
  ui_story_5026_50261402_29_dialog_content = "Correto! Como esperado do Mestre!",
  ui_story_5026_50261402_30_option_content = "Este não é o momento para jogos.",
  ui_story_5026_50261402_31_dialog_content = "Chubb...",
  ui_story_5026_50261402_32_dialog_content = "Vamos lá.",
  ui_story_5026_50261402_33_option_content = "Execute o link mental",
  ui_story_5026_50261402_34_dialog_content = "Chave Secreta sintetizada. Nome de login do operador: \"PlayerName\", Chubb.",
  ui_story_5026_50261402_35_dialog_content = "Verificação em andamento. Por favor, segure o Chubb que assumiu a forma da Chave Secreta.",
  ui_story_5026_50261402_36_dialog_content = "Essa coisa na minha mão está falando comigo?",
  ui_story_5026_50261402_37_dialog_content = "É muito mais leve do que parece.",
  ui_story_5026_50261402_38_dialog_content = "Verificação do operador concluída, Chubb.",
  ui_story_5026_50261402_39_dialog_content = "Eu não esperava que ainda falasse como um Chubb depois de se tornar assim.",
  ui_story_5026_50261402_40_dialog_content = "Não sei se devo chamar isso de legal ou fofo. Nenhum parece certo.",
  ui_story_5026_50261402_41_dialog_content = "As duas orelhas pontudas na ponta parecem combinar com a ranhura da bancada.",
  ui_story_5026_50261402_42_dialog_content = "Pode... servir como arma também?",
  ui_story_5026_50261402_43_dialog_content = "Aviso. Por favor, não o use para outros propósitos além de desbloquear o terminal de controle da Hyacinth Tower, Chubb.",
  ui_story_5026_50261402_44_dialog_content = "Por favor, coloque a chave secreta no slot para ativar a conexão manual, Chubb.",
  ui_story_5026_50261402_45_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_5026_50261402_46_dialog_content = "Conectado.",
  ui_story_5026_50261402_47_dialog_content = "A tentativa de estabelecer uma conexão com o Obelisco do Retorno... falhou. Obelisco do Retorno offline.",
  ui_story_5026_50261402_48_dialog_content = "Status do sistema de defesa: Desativado.",
  ui_story_5026_50261402_49_dialog_content = "O operador e o terminal de controle estão no modo mind-link.",
  ui_story_5026_50261402_50_dialog_content = "Como funciona esse sistema de defesa, exatamente?",
  ui_story_5026_50261402_51_dialog_content = "Recuperando documento de ajuda...",
  ui_story_5026_50261402_52_dialog_content = "O sistema de defesa ativa um <color=#FFB400>campo de força</color> que circunda a área residencial com a Hyacinth Tower no centro.",
  ui_story_5026_50261402_53_dialog_content = "O campo de força repelirá todas as formas de vida rotuladas como hostis.",
  ui_story_5026_50261402_54_dialog_content = "Um campo de força que mantém os inimigos afastados...",
  ui_story_5026_50261402_55_dialog_content = "Está longe do Acorde da Lei, mas não é como se tivéssemos outra escolha agora.",
  ui_story_5026_50261402_56_dialog_content = "Configuração de alvo hostil atual: Aurorianos.",
  ui_story_5026_50261402_57_dialog_content = "Por favor, emita um comando.",
  ui_story_5026_50261402_58_dialog_content = "<size=45>!!!</size>",
  ui_story_5026_50261402_59_dialog_content = "Ei, PlayerName? Olá?",
  ui_story_5026_50261402_60_dialog_content = "N-Nina! Eu posso explicar. O que você acabou de ouvir—",
  ui_story_5026_50261402_61_dialog_content = "Não ouvi nada desde que você pegou aquela chave.",
  ui_story_5026_50261402_62_dialog_content = "Você acabou de colocar a chave sem uma palavra, mas você parecia tão sombrio, é por isso que eu...",
  ui_story_5026_50261402_63_dialog_content = "Você... não ouviu nada?",
  ui_story_5026_50261402_64_dialog_content = "(Então a chave e o terminal estavam todos se comunicando comigo telepaticamente?)",
  ui_story_5026_50261402_65_dialog_content = "(Talvez seja assim que os Caelestites se comunicaram com suas criações...)",
  ui_story_5026_50261402_66_dialog_content = "Isso é... uma arma celestita?",
  ui_story_5026_50261402_67_dialog_content = "Parece bastante original.",
  ui_story_5026_50261402_68_dialog_content = "Mesmo que seja apenas uma chave, eu sei o que você quer dizer, Sanae.",
  ui_story_5026_50261402_69_dialog_content = "Quatro Chubbs empilhados juntos!",
  ui_story_5026_50261402_70_dialog_content = "Está me matando totalmente de fofura!",
  ui_story_5026_50261402_71_dialog_content = "(Certo...)",
  ui_story_5026_50261402_72_dialog_content = "(Seja qual for a verdade, não vou vacilar das escolhas que fiz.)",
  ui_story_5026_50261402_73_dialog_content = "(Agora, eu preciso mergulhar de volta no link...)",
  ui_story_5026_50261402_74_dialog_content = "(Hmm... É como... Uma vez que você percebe que está respirando, é difícil fazê-lo naturalmente.)",
  ui_story_5026_50261402_75_dialog_content = "(Foco!)",
  ui_story_5026_50261402_76_dialog_content = "Terminal System, você pode me ouvir?",
  ui_story_5026_50261402_77_dialog_content = "Aguardando entrada de comando.",
  ui_story_5026_50261402_78_dialog_content = "Marque todos os Eclipsites como hostis. Ative o sistema de defesa.",
  ui_story_5026_50261402_79_dialog_content = "Comando confirmado. Alvo: Eclipses.",
  ui_story_5026_50261402_80_dialog_content = "Progresso da inicialização do campo de força: 36%... 67%... 100%.",
  ui_story_5026_50261402_81_dialog_content = "<color=#FFB400>Iniciar ressonância sonata</color>.",
  ui_story_5026_50261501_1_dialog_content = "A-acabou?",
  ui_story_5026_50261501_2_dialog_content = "As marcações na Hyacinth Tower piscaram, mas Cloud Gardens não parece ser diferente.",
  ui_story_5026_50261501_3_dialog_content = "Poderia ter falhado? A tecnologia é antiga, afinal.",
  ui_story_5026_50261501_4_dialog_content = "Bem... Mesmo que eu não consiga ver nada, posso sentir que algo está diferente.",
  ui_story_5026_50261501_5_dialog_content = "O sistema de defesa é ativado. Os eclipsitos não poderão aproximar-se do campo de força, Chubb.",
  ui_story_5026_50261501_6_dialog_content = "Que bom...",
  ui_story_5026_50261501_7_dialog_content = "Isso se aplica a Eclipsitas tanto fora do campo de força quanto dentro dele, Chubb.",
  ui_story_5026_50261501_8_dialog_content = "O que? Então, se eles tentarem evitar a parede do campo de força, isso não significa...",
  ui_story_5026_50261501_9_dialog_content = "Eles se reunirão no centro de Cloud Gardens, que fica aqui na Hyacinth Tower, Chubb.",
  ui_story_5026_50261501_10_dialog_content = "Você deveria ter me dito isso antes de eu ativar as defesas!",
  ui_story_5026_50261501_11_dialog_content = "PlayerName não perguntou. Chubb.",
  ui_story_5026_50261501_12_dialog_content = "Eu... estou começando a pensar que você está escondendo uma agenda sob sua fachada fofa.",
  ui_story_5026_50261501_13_dialog_content = "Não entendo. Vem de novo, Chubb?",
  ui_story_5026_50261501_14_dialog_content = "Já que estamos no tópico de informações importantes – De qual fonte de energia o sistema de defesa se baseia? Não vai ficar sem energia de repente, vai?",
  ui_story_5026_50261501_15_dialog_content = "A energia cinética gerada por Chubbs enquanto se move fornece energia para outros Chubbs e a Torre Hyacinth. Chubb.",
  ui_story_5026_50261501_16_dialog_content = "Então vocês, Chubbs, não ficaram apenas vagando sem rumo...",
  ui_story_5026_50261501_17_dialog_content = "Nesse caso, Chubbs pode lutar?",
  ui_story_5026_50261501_18_dialog_content = "Talvez algo como combinar-se para formar um Chubb gigante através do link mental—",
  ui_story_5026_50261501_19_dialog_content = "Absolutamente não, Chubb.",
  ui_story_5026_50261501_20_dialog_content = "Isso foi um rápido não!",
  ui_story_5026_50261501_21_dialog_content = "Pelo menos não haverá mais Eclipsitas invadindo este lugar, certo?",
  ui_story_5026_50261501_22_dialog_content = "Portanto, não pareça tão chateado. Você fez o melhor que pode, PlayerName.",
  ui_story_5026_50261501_23_dialog_content = "Contratar mercenários de Umbraton é a única opção que tenho agora...?",
  ui_story_5026_50261501_24_dialog_content = "Minhas dívidas continuam se acumulando. Vice vai ficar chocada quando ela voltar...",
  ui_story_5026_50261501_25_dialog_content = "Bem, eu fiz o melhor que pude. Não há do que reclamar.",
  ui_story_5026_50261501_26_dialog_content = "Se eu tivesse notado os problemas de segurança do Cloud Gardens muito antes, nada disso teria acontecido.",
  ui_story_5026_50261501_27_dialog_content = "PlayerName...",
  ui_story_5026_50261501_28_dialog_content = "Senhorita Nina, devemos voltar para Umbraton agora.",
  ui_story_5026_50261501_29_dialog_content = "Agora mesmo? Mas PlayerName está em apuros agora!",
  ui_story_5026_50261501_30_dialog_content = "Tudo o que resta a fazer é chegar ao campo de força e esperar pela ajuda de Lady Bethel.",
  ui_story_5026_50261501_31_dialog_content = "Se isso puder ser feito, então os Eclipsites não devem mais representar uma ameaça.",
  ui_story_5026_50261501_32_dialog_content = "Por favor, perdoe-me por ser franco, senhorita, mas não há mais nada que você e eu possamos fazer.",
  ui_story_5026_50261501_33_dialog_content = "Como você pode dizer aquilo!? Isso é frio, mesmo para você, Minos.",
  ui_story_5026_50261501_34_dialog_content = "Mesmo que não possamos matar todos os Eclipsitas, ainda devemos fazer o que pudermos antes que os reforços cheguem!",
  ui_story_5026_50261501_35_dialog_content = "Por outro lado, PlayerName estaria falido, vivendo nas ruas e vendendo Chubbs para ganhar a vida!",
  ui_story_5026_50261501_36_dialog_content = "E-Não vai chegar a isso! ... Eu penso.",
  ui_story_5026_50261501_37_dialog_content = "O combate não é o seu forte, Srta. Nina. Quanta ajuda você pode ser?",
  ui_story_5026_50261501_38_dialog_content = "Não quero ver você se machucar em uma briga desnecessária.",
  ui_story_5026_50261501_39_dialog_content = "Uma briga desnecessária?",
  ui_story_5026_50261501_40_dialog_content = "Nada PlayerName precisa de ajuda está longe de ser desnecessário para mim!",
  ui_story_5026_50261501_41_dialog_content = "Deixar o trabalho para os profissionais é a solução mais eficiente e eficaz.",
  ui_story_5026_50261501_42_dialog_content = "Em outras palavras, você acha que sou tão frágil e frágil que apenas alguns eclipsitas me machucariam?",
  ui_story_5026_50261501_43_dialog_content = "Você está distorcendo minhas palavras, senhorita. Só estou pedindo que cumpra sua promessa.",
  ui_story_5026_50261501_44_dialog_content = "Se você insiste, por favor, me convença por meio de ações.",
  ui_story_5026_50261501_45_dialog_content = "Multar. Se é o que você quer.",
  ui_story_5026_50261501_46_dialog_content = "Tire sua arma.",
  ui_story_5026_50261501_47_dialog_content = "Eu vou te mostrar o quanto minhas habilidades de combate melhoraram.",
  ui_story_5026_50261501_48_dialog_content = "Fico feliz em ouvir isso. No entanto, não importaria se todos vocês se juntassem a mim.",
  ui_story_5026_50261501_49_option_content = "Como chegou a isso!?",
  ui_story_5026_50261501_50_dialog_content = "N-Nina! Vou te ajudar!",
  ui_story_5026_50261501_51_option_content = "Pare de brigar por mim já!",
  ui_story_5026_50261501_52_dialog_content = "Nós NÃO estamos brigando por você! Eu odeio como ele sempre age como se estivesse fazendo o que é melhor para mim!",
  ui_story_5026_50261501_53_dialog_content = "Parece que não tenho outra escolha.",
  ui_story_5026_50261502_1_dialog_content = "Isso é aterrorizante... Atravessou o chão como uma faca quente na manteiga...",
  ui_story_5026_50261502_2_dialog_content = "Você tem munição suficiente, senhorita?",
  ui_story_5026_50261502_3_dialog_content = "<size=45>Pare de me subestimar!</size>",
  ui_story_5026_50261502_4_dialog_content = "Ele está provocando você, Nina! Este não é o momento!",
  ui_story_5026_50261502_5_dialog_content = "Sanae, cubra o lado direito!",
  ui_story_5026_50261502_6_dialog_content = "G-Entendi! Você está pronto, Manae?",
  ui_story_5026_50261502_7_dialog_content = "Eu não perderia a chance de bater no meu superior!",
  ui_story_5026_50261502_8_dialog_content = "Apenas evite seu próximo ataque—",
  ui_story_5026_50261502_9_dialog_content = "<size=45>É isso! Agora mesmo!</size>",
  ui_story_5026_50261502_10_dialog_content = "Estou exausto...",
  ui_story_5026_50261502_11_dialog_content = "Que tal agora? H... *calça* Já teve o suficiente?",
  ui_story_5026_50261502_12_dialog_content = "(Mesmo que eu possa prever suas ações até certo ponto através da minha habilidade... É difícil acompanhar.)",
  ui_story_5026_50261502_13_dialog_content = "(Foi uma vitória apertada... só espero nunca mais ter que enfrentar o Minos...)",
  ui_story_5026_50261502_14_dialog_content = "Eu estou impressionado.",
  ui_story_5026_50261502_15_dialog_content = "Senhorita Nina, Sanae, e PlayerName...",
  ui_story_5026_50261502_16_dialog_content = "Seu desempenho superou minhas expectativas.",
  ui_story_5026_50261502_17_dialog_content = "Quanto tempo faz desde a última vez que provei a derrota...",
  ui_story_5026_50261502_18_dialog_content = "Parabéns, Dona Nina. Você ganhou.",
  ui_story_5026_50261502_19_dialog_content = "Tanto esta batalha como o nosso acordo.",
  ui_story_5026_50261502_20_dialog_content = "Se você pode me vencer em \"<color=#FFB400>só uma coisa</color> em Cloud Gardens\", você ganha.",
  ui_story_5026_50261502_21_dialog_content = "A batalha atendeu a essas condições perfeitamente.",
  ui_story_5026_50261502_22_dialog_content = "É melhor eu ser mais cuidadoso ao fazer um acordo verbal da próxima vez.",
  ui_story_5026_50261502_23_dialog_content = "Minos, você...",
  ui_story_5026_50261502_24_dialog_content = "Por favor, tome cuidado com sua linguagem, Srta. Mantenha sempre a elegância de uma dama.",
  ui_story_5026_50261502_25_dialog_content = "Eu não disse nada ainda!",
  ui_story_5026_50261502_26_dialog_content = "Sim, não usei toda a minha força em nossa batalha.",
  ui_story_5026_50261502_27_dialog_content = "No entanto, você ainda provou que é capaz de cuidar de si mesmo neste perigoso continente.",
  ui_story_5026_50261502_28_dialog_content = "Os companheiros que você escolheu não são servos, mas amigos que estarão ao seu lado.",
  ui_story_5026_50261502_29_dialog_content = "Sr. Minos...",
  ui_story_5026_50261502_30_dialog_content = "Vou relatar isso ao Mestre Andersen.",
  ui_story_5026_50261502_31_dialog_content = "De acordo com nosso acordo, eu deveria me despedir de você agora, mas sinto muito.",
  ui_story_5026_50261502_32_dialog_content = "Como pode ser claramente testemunhado, danifiquei severamente Cloud Gardens em nossa batalha.",
  ui_story_5026_50261502_33_dialog_content = "Eu era um convidado, mas eu destruí PlayerNameA casa dos Chubbs...",
  ui_story_5026_50261502_34_dialog_content = "Mesmo que você seja apenas meu empregador temporário e aprendiz, eu traí sua confiança.",
  ui_story_5026_50261502_35_dialog_content = "Sr. Navigator, sinto muito por isso.",
  ui_story_5026_50261502_36_dialog_content = "Eu sei que não há como compensá-lo pelo que fiz com as coisas que você ama...",
  ui_story_5026_50261502_37_dialog_content = "Mas, por favor, permita-me a chance de compensar o que fiz restaurando Cloud Gardens.",
  ui_story_5026_50261502_38_dialog_content = "Não se preocupe. Eu sou muito bom em limpar todas as manchas, lixo e vermes.",
  ui_story_5026_50261502_39_dialog_content = "O que, claro, inclui todos os convidados indesejados em Cloud Gardens.",
  ui_story_5026_50261502_40_dialog_content = "Você quer dizer... Você vai cuidar de todos os Eclipsites?",
  ui_story_5026_50261502_41_dialog_content = "Você não vai aceitar minhas desculpas?",
  ui_story_5026_50261502_42_dialog_content = "Eu aceito, claro. É apenas-",
  ui_story_5026_50261502_43_dialog_content = "Não precisa dizer mais nada. Eu só quero mostrar minha sinceridade.",
  ui_story_5026_50261502_44_dialog_content = "(Como é que eu sinto que fui tocado...)",
  ui_story_5026_50261502_45_dialog_content = "(Mas de uma forma boa?)",
  ui_story_5026_50261502_46_dialog_content = "Você deve estar cansado.",
  ui_story_5026_50261502_47_dialog_content = "Sanae, por favor, leve esses dois para a Hyacinth Tower para descansar. Já coloquei a mesa lá.",
  ui_story_5026_50261502_48_dialog_content = "Sim, senhor!",
  ui_story_5026_50261502_49_dialog_content = "Hum... Sr. Navegador, Nina.",
  ui_story_5026_50261502_50_dialog_content = "Eu acho... tomar uma xícara de chá primeiro?",
  ui_story_5026_50261601_1_dialog_content = "Esse é o relato completo da minha viagem a Cloud Gardens.",
  ui_story_5026_50261601_2_dialog_content = "A missão falhou por causa da minha própria imprudência. Não tenho desculpa.",
  ui_story_5026_50261601_3_dialog_content = "Mas confio na senhorita Nina para fazer suas próprias escolhas.",
  ui_story_5026_50261601_4_dialog_content = "Sua determinação e trabalho duro, paixão e persistência, são como você.",
  ui_story_5026_50261601_5_dialog_content = "Minos...",
  ui_story_5026_50261601_6_dialog_content = "Sim senhor?",
  ui_story_5026_50261601_7_dialog_content = "Quando Nina era jovem, ela corria pela metade do pátio apenas para me mostrar uma linda flor que ela havia encontrado.",
  ui_story_5026_50261601_8_dialog_content = "Mas depois que ela cresceu, ela nem me deixou comprar nenhum de seus trabalhos.",
  ui_story_5026_50261601_9_dialog_content = "É tão errado para mim querer ter algo que ela desenhou e criou sozinha?",
  ui_story_5026_50261601_10_dialog_content = "Eu queria ter pelo menos dois conjuntos de cada tipo e cor para mim... Um conjunto para coleção, outro para uso real.",
  ui_story_5026_50261601_11_dialog_content = "Além de mais um conjunto para ostentar na frente de Istvan.",
  ui_story_5026_50261601_12_dialog_content = "E três conjuntos adicionais, caso algo seja danificado ou perdido em um acidente.",
  ui_story_5026_50261601_13_dialog_content = "E enviar alguém para comprá-los para mim em segredo não foi um grande problema...",
  ui_story_5026_50261601_14_dialog_content = "Deixá-la descobrir foi o único erro que cometi.",
  ui_story_5026_50261601_15_dialog_content = "Eu sabia! Você realmente não refletiu sobre o que fez!",
  ui_story_5026_50261601_16_dialog_content = "Nina? Você voltou? Minos, meus olhos estão me enganando?",
  ui_story_5026_50261601_17_dialog_content = "Não, eles não são, Mestre.",
  ui_story_5026_50261601_18_dialog_content = "A única razão pela qual eu não queria que você comprasse minhas criações é que você...",
  ui_story_5026_50261601_19_dialog_content = "Você sempre quer sair exibindo minhas criações meio decentes em todas as reuniões sociais!",
  ui_story_5026_50261601_20_dialog_content = "É tão embaraçoso!",
  ui_story_5026_50261601_21_dialog_content = "Você está sendo muito modesto, minha querida. Eu nunca fui nada além de sincero em minha bajulação.",
  ui_story_5026_50261601_22_dialog_content = "E foi necessário comprar completamente minha loja?",
  ui_story_5026_50261601_23_dialog_content = "Todos os nossos guardas e escoltas merecem ter armas tão estéticas e práticas.",
  ui_story_5026_50261601_24_dialog_content = "Eu só queria deixá-lo orgulhoso por fazer melhor do que Bethel...",
  ui_story_5026_50261601_25_dialog_content = "Minos já foi extremamente útil para você quando tinha a minha idade, não foi?",
  ui_story_5026_50261601_26_dialog_content = "Você não precisa provar nada para mim ou se comparar com mais ninguém.",
  ui_story_5026_50261601_27_dialog_content = "Tenho orgulho de você desde o momento do seu nascimento.",
  ui_story_5026_50261601_28_dialog_content = "Mas há outras razões pelas quais eu quero ter sucesso também!",
  ui_story_5026_50261601_29_dialog_content = "Quero que meus designs se tornem parte da vida das pessoas comuns.",
  ui_story_5026_50261601_30_dialog_content = "Para conseguir isso, preciso de feedback real do cliente, seja bom ou ruim.",
  ui_story_5026_50261601_31_dialog_content = "Essa é a única maneira que eu posso empurrar meu negócio para a frente.",
  ui_story_5026_50261601_32_dialog_content = "<anim type=Shake>Nina... Você realmente cresceu...</anim>",
  ui_story_5026_50261601_33_dialog_content = "<size=45>P-Por que você está chorando?</size>Papai, por que você é tão dramático... Você está me envergonhando.",
  ui_story_5026_50261601_34_dialog_content = "Eu só queria que sua mãe pudesse ter ouvido o que você acabou de dizer.",
  ui_story_5026_50261601_35_dialog_content = "Ah, eu te disse que conheci esse interessante celestita em Eraveil?",
  ui_story_5026_50261601_36_dialog_content = "Se não fosse por ele, eu não teria percebido minhas falhas e imaturidade na hora de começar um negócio.",
  ui_story_5026_50261601_37_dialog_content = "Eu também não teria percebido que precisava de tempo para pensar e me acalmar, e ser honesto com você sobre meus sentimentos.",
  ui_story_5026_50261601_38_dialog_content = "A maneira como ele tentava desesperadamente agarrar algo com as próprias mãos...",
  ui_story_5026_50261601_39_dialog_content = "Isso me deu um vislumbre de como você me vê.",
  ui_story_5026_50261601_40_dialog_content = "Hmph! E você! Embora eu tenha percebido seus verdadeiros motivos imediatamente, devo dizer isso!",
  ui_story_5026_50261601_41_dialog_content = "Do jeito que você me provocou, Minos, você realmente é bom em me irritar!",
  ui_story_5026_50261601_42_dialog_content = "Obrigado pelo elogio.",
  ui_story_5026_50261601_43_dialog_content = "Isso não foi um elogio!",
  ui_story_5026_50261601_44_dialog_content = "Tudo bem... Acho que é de certa forma.",
  ui_story_5026_50261601_45_dialog_content = "O Caelestita também mantém em sua companhia um bando de adoráveis Chubbs. Pena que não pude trazer um de volta comigo...",
  ui_story_5026_50261601_46_dialog_content = "E Sanae me ensinou a pescar! Também...",
  ui_story_5026_50261601_47_dialog_content = "Oh! Deixe-me tirar o que estou vestindo agora. Eu volto já! Mantenha sua agenda clara para mim!",
  ui_story_5026_50261601_48_dialog_content = "Minos.",
  ui_story_5026_50261601_49_dialog_content = "Sim senhor?",
  ui_story_5026_50261601_50_dialog_content = "Quem é PlayerName?",
  ui_story_5026_50261601_51_dialog_content = "PlayerName pode ser jovem, mas, no entanto, é uma pessoa de bom caráter.",
  ui_story_5026_50261601_52_dialog_content = "Hmph! Não acredito que o Último Caelestita seja um pacifista.",
  ui_story_5026_50261601_53_dialog_content = "Sua habilidade inata torna impossível para eles evitarem se envolver em assuntos mundanos.",
  ui_story_5026_50261601_54_dialog_content = "Honestidade e bondade não são suficientes para garantir a sobrevivência neste mundo.",
  ui_story_5026_50261601_55_dialog_content = "Você está certo.",
  ui_story_5026_50261601_56_dialog_content = "A única maneira de manter a paz é ser aquele que segura o bastão maior.",
  ui_story_5026_50261601_57_dialog_content = "Ou... por estar do lado de quem segura a vara maior.",
  ui_story_5026_50261601_58_dialog_content = "Esqueça tudo isso... Estou aposentado. Vou deixar essas preocupações mundanas para o Senhor das Sombras. Mais importante...",
  ui_story_5026_50261601_59_dialog_content = "Minha querida Nina parece ter este celestita em alta consideração e se preocupa com ele. Isso é verdade?",
  ui_story_5026_50261601_60_dialog_content = "Como de costume, todos os homens em contato com a Srta. Nina são investigados e observados minuciosamente.",
  ui_story_5026_50261601_61_dialog_content = "Você tem três minutos. Quero todas as informações relacionadas a esse garoto, incluindo qualquer coisa que possa ter aparecido no Umbraton Daily.",
  ui_story_5026_50261601_62_dialog_content = "Como desejar.",
  ui_story_5026_50261601_63_dialog_content = "Está tão quieto.",
  ui_story_5026_50261601_64_dialog_content = "(Pouco depois de Minos partir, Nina e Sanae também voltaram para Umbraton.)",
  ui_story_5026_50261601_65_dialog_content = "(Espero que Nina possa fazer as pazes com seu pai.)",
  ui_story_5026_50261601_66_dialog_content = "(Mesmo que ela ainda não tenha desistido daquele plano de dominação mundial dela...)",
  ui_story_5026_50261601_67_dialog_content = "Há muitas coisas que preciso descobrir para integrar sua ideia de \"porto seguro\" ao meu plano.",
  ui_story_5026_50261601_68_dialog_content = "Essa foi a razão pela qual você rejeitou meu plano inicialmente, certo?",
  ui_story_5026_50261601_69_dialog_content = "Ser incapaz de ganhar a confiança do meu parceiro mostra o quão imaturo eu sou.",
  ui_story_5026_50261601_70_dialog_content = "Se for assim, não posso mais perder meu tempo neste lugar de lazer.",
  ui_story_5026_50261601_71_dialog_content = "Decidi voltar para casa e aprender gestão de negócios com meu pai.",
  ui_story_5026_50261601_72_dialog_content = "Mas prometo a você que voltarei para pedir para trabalhar com você assim que aprender tudo o que puder.",
  ui_story_5026_50261601_73_dialog_content = "D-Não se atreva a esquecer!",
  ui_story_5026_50261601_74_dialog_content = "(Minos decidiu me dizer quem era Nina porque viu minha influência sobre ela?)",
  ui_story_5026_50261601_75_dialog_content = "(Se sim... Então ele não estava apenas testando Nina, mas também eu...)",
  ui_story_5026_50261601_76_dialog_content = "(Talvez tenha sido seu plano desde o momento em que nos conhecemos.)",
  ui_story_5026_50261601_77_dialog_content = "(Como esse mordomo é aterrorizante...)",
  ui_story_5026_50261601_78_dialog_content = "(No final, não consegui recrutar um gerente, mas os Chubbs devem ser capazes de me ajudar a cuidar de Cloud Gardens.)",
  ui_story_5026_50261601_79_dialog_content = "(Também aprendi bastante desde que ativei o sistema de defesa da Hyacinth Tower.)",
  ui_story_5026_50261601_80_dialog_content = "Agora, então, eu deveria começar as tarefas em torno do Cloud Gardens.",
  ui_story_5026_50261601_81_dialog_content = "Primeiro, isso... como se chama mesmo, uma lista de funcionários?",
  ui_story_5026_50261601_82_dialog_content = "Por que você está sozinho aqui, PlayerName? Onde está Nina e todos os outros?",
  ui_story_5026_50261601_83_dialog_content = "Muitos amigos seus estavam dispostos a ajudar depois de ouvir sobre sua situação.",
  ui_story_5026_50261601_84_dialog_content = "Mesmo que a maioria deles não pudesse ir devido a compromissos anteriores, ainda consegui recrutar alguma ajuda.",
  ui_story_5026_50261601_85_dialog_content = "Mas parece que você já cuidou dos Eclipsites.",
  ui_story_5026_50261601_86_dialog_content = "É uma longa história... Você não recebeu minha mensagem, Bethel?",
  ui_story_5026_50261601_87_dialog_content = "Eu reembolsarei suas despesas de transporte...",
  ui_story_5026_50261601_88_dialog_content = "Não hesite em contactar-me se precisar de trabalho a ser feito no futuro.",
  ui_story_5026_50261601_89_dialog_content = "Você nos ajudou durante o incidente da Guilda Leão Azul. Eu gostaria muito de ter a chance de retribuir.",
  ui_story_5026_50261601_90_dialog_content = "Só fiz o que deveria ter feito. Você não me deve nada...",
  ui_story_5026_50261601_91_dialog_content = "Você é muito gentil, PlayerName.",
  ui_story_5026_50261601_92_dialog_content = "Pense assim, então: Ajudar o Último Caelestita a reconstruir sua casa e se estabelecer é bom para a imagem dos Mercenários da Chama Branca.",
  ui_story_5026_50261601_93_dialog_content = "Um ganha-ganha, se você quiser.",
  ui_story_5026_50261601_94_dialog_content = "Eu vejo. Obrigado pela ajuda desde já, então.",
  ui_story_5026_50261601_95_dialog_content = "Oh, todos os trabalhos já estão ocupados?",
  ui_story_5026_50261601_96_dialog_content = "Já que estou aqui, é melhor fazer alguns negócios... Acho que uma boa pintura combinaria bem com sua nova casa, PlayerName.",
  ui_story_5026_50261601_97_dialog_content = "Como chefe, você precisa de alguma arte para tornar este lugar mais sensual e mostrar seu gosto.",
  ui_story_5026_50261601_97X1_dialog_content = "Se você não gosta de pinturas, que tal uma estátua de um artista que está em alta em Umbraton?",
  ui_story_5026_50261601_97X2_dialog_content = "Tsk, como um canino, não posso deixar de admitir que ele é mais dotado no departamento de aparência.",
  ui_story_5026_50261601_98_dialog_content = "Obrigado, mas não obrigado.",
  ui_story_5026_50261601_99_dialog_content = "Não diga isso! Dê uma olhada neste folheto. Estas são todas grandes pinturas de artistas renomados...",
  ui_story_5026_50261601_100_dialog_content = "Uau!",
  ui_story_5026_50261601_101_dialog_content = "É a casa deste cachorro? Tão espaçoso!",
  ui_story_5026_50261601_102_dialog_content = "Não do cachorro, mas PlayerName's.",
  ui_story_5026_50261601_103_dialog_content = "A nova casa do Puppy é mais espaçosa que a Colossus? Eu adoraria correr por aqui!",
  ui_story_5026_50261601_104_dialog_content = "Que tal um esconde-esconde?",
  ui_story_5026_50261601_105_dialog_content = "Vamos todos brincar de esconde-esconde!",
  ui_story_5026_50261601_106_dialog_content = "Cuidado, vocês dois! Não tropece nas coisas!",
  ui_story_5026_50261601_107_dialog_content = "Sinta-se à vontade para colidir com esses dois aproveitadores, mas observe as relíquias. Este lugar é uma antiga ruína celestita.",
  ui_story_5026_50261601_108_dialog_content = "As relíquias de celestita são bastante raras mesmo em Umbraton. Imagino que cada um deles daria uma bela exibição na minha futura loja.",
  ui_story_5026_50261601_109_dialog_content = "Há algumas coisas no Museu, mas não sei se contam como relíquias.",
  ui_story_5026_50261601_110_dialog_content = "Apesar de parecer que não temos mais emprego, valeu a pena fazer essa viagem só para poder ver sua coleção.",
  ui_story_5026_50261601_111_dialog_content = "Eu posso te mostrar o caminho! Chubb!",
  ui_story_5026_50261601_112_dialog_content = "Uau, olhe para essa bela proporção... Sinto algo precioso em você.",
  ui_story_5026_50261601_113_dialog_content = "Chubb?",
  ui_story_5026_50261601_114_dialog_content = "Não importa o Museu. Se importa se eu verificar você um pouco?",
  ui_story_5026_50261601_115_dialog_content = "Nossa, aquele momento de paz agora foi como um sonho...",
  ui_story_5026_50261601_116_dialog_content = "Nada em você é chato e corajoso Navigator.",
  ui_story_5026_50261601_117_dialog_content = "Kleken!",
  ui_story_5026_50261601_118_dialog_content = "Aonde no mar revolto esta nova arca irá levá-lo?",
  ui_story_5026_50261601_119_dialog_content = "Os jardins do céu mergulhando fundo no oceano devem ser uma vista de se ver!",
  ui_story_5026_50261601_120_dialog_content = "Eu farei o meu melhor para nunca deixar isso acontecer...",
  ui_story_5026_50261601_121_dialog_content = "Ha... De que loucura ele está falando dessa vez?",
  ui_story_5026_50261601_122_dialog_content = "Você também, PlayerName. Você ainda parece tão desajeitado como sempre.",
  ui_story_5026_50261601_123_dialog_content = "Hidra? Eu não achei que você estaria aqui também—",
  ui_story_5026_50261601_124_dialog_content = "Tchau!",
  ui_story_5026_50261601_125_dialog_content = "Você acabou de chegar aqui!",
  ui_story_5026_50261601_126_dialog_content = "Não é como se eu quisesse vir! Aquele polvo estúpido mentiu para mim sobre como o chefe precisava de mim aqui para um trabalho.",
  ui_story_5026_50261601_127_dialog_content = "É muito amplo e aberto aqui. Está deixando os Lobos das Sombras inquietos, como aqueles cachorros ali.",
  ui_story_5026_50261601_128_dialog_content = "Não pode ser ajudado. Está na nossa natureza!",
  ui_story_5026_50261601_129_dialog_content = "<size=40>Vamos! Vamos! Vamos brincar de esconde-esconde!</size>",
  ui_story_5026_50261601_130_dialog_content = "<size=45>Fufufu!</size>",
  ui_story_5026_50261601_131_dialog_content = "<size=50>É tão barulhento! Saia de perto de mim!</size>",
  ui_story_5026_50261601_132_dialog_content = "... Eu não esperava que as coisas fossem assim.",
  ui_story_5026_50261601_133_dialog_content = "Colora-me chocado. Sem um trabalho a fazer, os profissionais da Umbraton são apenas um bando de crianças problemáticas.",
  ui_story_5026_50261601_134_dialog_content = "Não é bom ver cachorrinhos brincando e perseguindo uns aos outros em um campo?",
  ui_story_5026_50261601_135_dialog_content = "Parece que essa comoção não vai acabar por um tempo.",
  ui_story_5026_50261601_136_dialog_content = "Er... Se vocês não estão com pressa...",
  ui_story_5026_50261601_137_dialog_content = "Por que você não se senta para tomar um chá?",
  ui_story_5026_50261601_138_dialog_content = "<color=#e8d9bb>Na Ponte de Soroz, alguns dias depois</color>",
  ui_story_5026_50261601_139_dialog_content = "Então... você passou por todas essas coisas enquanto estávamos fora, hein?",
  ui_story_5026_50261601_140_dialog_content = "Estou feliz por você, mas também me sinto um pouco para baixo por algum motivo.",
  ui_story_5026_50261601_141_dialog_content = "Vice...",
  ui_story_5026_50261601_142_dialog_content = "É melhor você me mostrar a Espada Chubb se tiver a chance de fazê-la novamente no futuro!",
  ui_story_5026_50261601_143_dialog_content = "Você está se sentindo para baixo por causa disso!?",
  ui_story_5026_50261601_144_dialog_content = "Um campo de força... Eu não sabia que a Hyacinth Tower podia fazer isso.",
  ui_story_5026_50261601_145_dialog_content = "A segurança de Cloud Gardens era algo que me preocupava.",
  ui_story_5026_50261601_146_dialog_content = "Felizmente, tudo foi resolvido antes que qualquer dano permanente pudesse ser feito.",
  ui_story_5026_50261601_147_dialog_content = "Você defendeu sua casa por conta própria. Bom trabalho, PlayerName.",
  ui_story_5026_50261601_148_dialog_content = "Obrigado, Carlão.",
  ui_story_5026_50261601_149_dialog_content = "Mas não fiz isso sozinho. Eu não poderia ter feito isso sem Nina e todos os outros.",
  ui_story_5026_50261601_150_dialog_content = "Assim como Cloud Gardens não estaria aqui agora sem a ajuda de todos.",
  ui_story_5026_50261601_151_dialog_content = "...",
  ui_story_5026_50261601_152_dialog_content = "Depois de saber o que eu fiz sobre os Caelestites do Obelisco do Retorno e dos Jardins das Nuvens...",
